import State from './State';
import FlowExecutor from './FlowExecutor';
import { FlowHarness, FlowStepInstruction } from 'jibo-flow-core';

/**
 * A class that couples a FlowExecutor with a FlowHarness.
 * It is responsible for determining:
 * 1) which harness to attach,
 * 2) when and where in a flow the harness steps are to be executed, and
 * 3) executing the harness steps.
 */

export default class FlowHarnesser {
    private _steps:FlowStepInstruction [];
    private _currentStep = 0;

    constructor(public flowExecutor:FlowExecutor, public harnesses:FlowHarness[]) {
        this._listenForHarnessAttachment();
    }

    /**
     * Execute all the harness steps that are ready, given the current executor's state.
     * @param {State} state the flow executor's current state
     * @returns {State}
     */
    check(state:State) {
        while (this._steps
        && this._currentStep < this._steps.length
        && this._isHarnessStepReady(state, this._currentStep)) {
            state = this._evaluateHarnessStep(state, this._currentStep++);
        }
        return state;
    }

    /**
     * Watch the FlowExecutor as it runs, seeing if there's a harness
     * that begins with a matching condition, and if so, attaching it.
     */
    private _listenForHarnessAttachment() {
        if (this.harnesses && this.harnesses.length !== 0) {
            this.flowExecutor.on('constructing-activity', (info) => {
                for (let i = 0; i < this.harnesses.length; i++) {
                    let steps = this.harnesses[i].getSteps();
                    let step = steps[0];
                    if (
                        (!step.activity || step.activity === info.name) &&
                        (!step.class || step.class === info.type) &&
                        (!step.flow || info.uri.endsWith(step.flow + '.flow'))) {

                        // Claim the first matching harness as our own and remove it
                        // from the list of available harnesses.
                        console.log('Attaching flow harness', steps[0]);
                        this._steps = steps;
                        this.harnesses.splice(i, 1)[0];
                        this._setupForHarness(steps);
                        break;
                    }
                }
            });
        }
    }

    /**
     * Do any setup required to run the harness.
     */
    private _setupForHarness(steps) {
        for (let step of steps) {
            if (step.say) {
                // If we're using simulated ASR input, arrange that
                // the simulated  TTS comes out as fast as possible.
                step.ssm.TTSService.instance.setMode('Instant');
            }
        }
    }

    // where: activity: 'ActivityName', class: 'ActivityClass', procedure: 'Flow-name' (without .flow suffix)
    // when: at: 'start', at: 'update', at: 'end', delay: seconds (after updating given number of seconds)  (default is 'update')

    /**
     * CHeck to see if the flow executor is at a place that matches the next step in the harness.
     * @param state
     * @param stepNumber
     * @returns {boolean}
     * @private
     */
    private _isHarnessStepReady(state:State, stepNumber:number) {
        let ready = false;
        let step = this._steps[stepNumber];

        if (
            (!step.activity || step.activity === this.flowExecutor.context.current_activity.name) &&
            (!step.class || step.class === this.flowExecutor.context.current_activity.class) &&
            (!step.flow || step.flow === this.flowExecutor.context.current_procedure.name)
        ) {
            let at = step.at || 'update';
            if ((at === 'start' && state === State.READY)
                || (at === 'update' && state === State.IN_PROGRESS)
                || (at === 'end' && state === State.DONE)) {

                if (!step.delay) {
                    ready = true;
                } else {
                    step.timestamp = step.timestamp || Date.now();
                    if (Date.now() - step.timestamp > step.delay * 1000) {
                        ready = true;
                    }
                }
            }
        }
        return ready;
    }


    // action: do: () => {arbitrary code -- but return value at 'end' is transition}
    // action: assert () => {arbitrary code with boolean return value whether assert passed or failed}
    // action: say: 'arbitrary string of synthetic ASR input'
    // Result of evaluation:
    // assertion: true/false,
    // executed: true/false
    // result: result of do invocation

    /**
     * Execute the next step in the harness.
     * @param state
     * @param stepNumber
     * @returns {State}
     * @private
     */
    private _evaluateHarnessStep(state:State, stepNumber:number) {
        let finalState = state;
        let step = this._steps[stepNumber];
        if (step.stub) {
            step.result = step.stub(this.flowExecutor.context.current_activity, this.flowExecutor.context.notepad, this.flowExecutor.blackboard);
            this.flowExecutor.context.current_activity.result = step.result;
            finalState = State.DONE;
        }
        if (step.do) {
            step.result = step.do(this.flowExecutor.context.current_activity, this.flowExecutor.context.notepad, this.flowExecutor.blackboard);
        }
        if (step.assert) {
            step.assertion = step.assert(this.flowExecutor.context.current_activity, this.flowExecutor.context.notepad, this.flowExecutor.blackboard);
            if (!step.assertion) {
                throw new Error(step.it);
            }
        }
        if (step.say) {
            step.ssm.ASRService.instance.onWordsReceived({
                words: step.say,
                incremental: false,
                speaker: "",
                final: true
            });
        }
        step.executed = true;
        return finalState;
    }
}