import {LoaderCallback as Callback, AssetManager, Task} from 'jibo-loader';
import Runtime from '../../Runtime';

//pool of Worker threads, as the startup time of a Worker is probably longer than we'd like
const workerPool:Worker[] = [];

/**
 * Loads an image and sets it up for Pixi to use as a PIXI.Texture.
 * @class CompressedImageTask
 * @memberof jibo.loader
 * @private
 * @param {String} asset.src The texture image path. Must end in .dds or .crn
 * @param {Boolean} [asset.remote=false] `true` to force a remote download over XMLHttpRequest.
 * @param {Number} [asset.timeout=0] Number of milliseconds for remote load to timeout.
 * @param {Boolean|String} [asset.cache=false] `true` to cache the result. String to add to a specific cache.
 * @param {String} [asset.id] The ID of the task.
 * @param {Function} [asset.complete] The callback to call when the load is completed.
 */

class CompressedImageTask extends Task
{
    static priority:number;
    public src:string;

    /**
     * Tests if an asset should be loaded.
     * @method jibo.loader.CompressedImageTask.test
     * @static
     * @param {Object} asset The asset to test.
     * @return {Boolean} `true` if the asset qualifies for this task.
     */
    static test(asset:any): boolean
    {
        return asset.src && /(\.dds|\.crn)$/.test(asset.src);
    }

    constructor(manager:AssetManager, asset:any)
    {
        super(manager, asset, asset.src);
        
        //after we know PIXI has been loaded, and also when we actually need to load a thing,
        //mix in the Compressed Textures plugin
        // if (!(PIXI as any).compressedTextures) {
        //     require('pixi-compressed-textures');
        // }

        /**
         * The atlas source path.
         * @name jibo.loader.CompressedImageTask#src
         * @type {String}
         */
        this.src = this.prepare(asset.src);
    }

    /**
     * Starts the load.
     * @method jibo.loader.CompressedImageTask#start
     * @param {jibo.loader.Task~completeCallback} callback Callback to call when the load is done
     */
    start(callback:Callback):void
    {
        if ((/\.crn$/.test(this.src))) {
            this.unCrunch(this.src, callback);
            return;
        }
        // Load the file via XHR
        const xhr = new XMLHttpRequest();
        xhr.addEventListener('load', (ev) => {
            const output = (PIXI as any).compressedTextures.CompressedImage.loadFromArrayBuffer(xhr.response, this.src);
            callback(null, output);
        }, false);
        xhr.addEventListener('error', function(err) {
            console.warn('had an XHR error: ', err);
            callback(err as any);
        });
        xhr.open('GET', this.src, true);
        xhr.responseType = 'arraybuffer';
        xhr.send();
    }
    
    private unCrunch(data:string, callback:Callback):void {
        let loader:Worker = workerPool.pop() || new Worker(Runtime.instance.utils.PathUtils.getAssetUri('jibo://resources/workerJS/webgl-texture-util.js'));
        
        // The worker's message handler.
        loader.onmessage = (msg) => {
            //repool loader, we no longer need it
            loader.onmessage = null;
            workerPool.push(loader);
            if (msg.data.error) {
                callback(msg.data.error);
                return;
            }
            const data = msg.data;
            let output;
            const CompressedImage = (PIXI as any).compressedTextures.CompressedImage;
            if (data.format) {
                output = new CompressedImage(this.src, data.data, 'CRN', data.width, data.height, data.levels, data.format);
            } else {
                output = CompressedImage.loadFromArrayBuffer(data.data, this.src);
            }
            callback(null, output);
        };
        
        //send message to start loading
        //data = String(data) as any;
        loader.postMessage({src:data});
    }
}

export default CompressedImageTask;
