/**
 * @typedef jibo.face.List~ListOptions
 * @description Interface - Configuration values for creating a List.
 * @prop {String} [id] - Identifier for list.
 * @prop {Object} [assets] - List of required asset descriptors, generally lists do not specify assets as they act as container.
 * @prop {Object} [position] - Object in point format, if axis is horizontal uses x, if vertical uses y (vertical is not currently supported).
 * @prop {Object} [componentConfigs] - Object containing list of element configurations contain within list.
 * @prop {boolean} [noPan = false] - If `true` disables gesture for panning left and right on list.
 * @prop {number} [elementsPerPage] - Number of elements that will appear fully on screen at a time.
 * @prop {number} [pageIndex] - Index of active page of list.
 * @prop {number} [indexOfAction] - Index of the element within list that last triggered an action.
 * @prop {Object} [elementDimensions] - Width and height of the elements given in point format, x is width and y is height.
 * @prop {number} [elementBuffer] - Minimum space between the elements in the list.
 * @prop {Object} [defaultElement] - Default configuration for the elements in the list.
 * @prop {Boolean} [dynamic = false] - If 'true' list elements will load as needed, if 'false' all elements assets are loaded with view.
 * @prop {Boolean} [dynamicPreload = true] -  Use only when `dynamic` is `true`.
 * If `true` will load the assets for active elements prior to open, if `false` assets for active elements start laod after open is called.
 * @prop {number} [dynamicBuffer] - Use only when `dynamic` is `true`. Number of pages on either side of current page that will be loaded.
 */
export interface ListOptions {
    id?:string;
    assets?:any;
    position?:any;
    componentConfigs?:any;
    dynamic?:boolean;
    dynamicPreload?:boolean;
    dynamicBuffer?:number;
    noPan?:boolean;
    elementsPerPage?:number;
    pageIndex?:number;
    indexOfAction?:number;
    elementDimensions?:any;
    elementBuffer?:number;
    defaultElement?:any;
};

/**
 * Format for methods that will handle destroy transitioning for an Element
 * @callback jibo.face.List~ElementTransition
 * @param {jibo.face.Element} element - Element to transition.
 * @param {Function} done - Called once transition is complete.
 */
export type ElementTransition = (element:Element, done:() => void) => any;

enum Movement {
    NONE,
    PAN,
    SWIPE
}

enum PanCase {
    STILL,
    DYNAMIC,
    CLAMP_LEFT,
    CLAMP_RIGHT
}

