import { Event, EventContainer } from 'jibo-typed-events';
import {PresenceRecord} from "./LPSRecords";
import {LPSEntity} from "jibo-common-types";


/**
 * @description
 * IdentityEvents that can be subscribed to.
 * ```
 * jibo.lps.identity.events.presenceStarted.on(() => {});
 * ```
 * @memberof jibo.lps.identity
 * @class IdentityEvents
 */
export class IdentityEvents extends EventContainer {

    /**
     * Fires upon transition from nobody being present to at least one person being present
     * in the robot's environment.
     * @name jibo.lps.identity.IdentityEvents#presenceStarted
     * @type {Event<any>}
     */
    public presenceStarted = new Event<PresenceRecord>("Presence Started");

    /**
     * Fires upon transition from at least one person being present to nobody being present
     * in the robot's environment.
     * @name jibo.lps.identity.IdentityEvents#presenceEnded
     * @type {Event<any>}
     */
    public presenceEnded = new Event<PresenceRecord>("Presence Ended");

    /**
     * Fires when a person in the robot's environment becomes uniquely identified.
     * @name jibo.lps.identity.IdentityEvents#idAcquired
     * @type {Event<string>}
     */
    public idAcquired = new Event<PresenceRecord>("ID Acquired");

    /**
     * Fires when a previously-identified person disappears.
     * @name jibo.lps.identity.IdentityEvents#idLost
     * @type {Event<string>}
     */
    public idLost = new Event<PresenceRecord>("ID Lost");
    /**
     * Fires when a new face enters Jibo's FOV
     * @name jibo.lps.identity.IdentityEvents#visibleFaceStarted
     * @type {Event<string>}
     */
    public visibleFaceStarted = new Event<LPSEntity>("Visible Face Started");
    /**
     * Fires when a face leaves Jibo's FOV.
     * @name jibo.lps.identity.IdentityEvents#visibleFaceStopped
     * @type {Event<string>}
     */
    public visibleFaceStopped = new Event<LPSEntity>("Visible Face Stopped");

    public constructor() {
        super();
    }
}


/**
 * @description
 * PresenceEvents that can be subscribed to. Used as a helper to `PresenceRecords`
 * in `DataConverter`.
 * @memberof jibo.lps.identity
 * @class PresenceEvents
 * @intdocs
 */
export class PresenceEvents extends EventContainer {

    /**
     * Fires upon transition from nobody being present to at least one person being present
     * in the robot's environment.
     * @name jibo.lps.identity.PresenceEvents#presenceStarted
     * @type {Event<any>}
     */
    public presenceStarted = new Event<any>("Presence Started");

    /**
     * Fires upon transition from at least one person being present to nobody being present
     * in the robot's environment.
     * @name jibo.lps.identity.PresenceEvents#presenceEnded
     * @type {Event<any>}
     */
    public presenceEnded = new Event<any>("Presence Ended");
    public constructor() {
        super();
    }
}
