import Behavior from '../Behavior';
import Status from '../Status';
import Runtime from '../../Runtime';
import {PathUtils} from 'jibo-plugins';
import KeysAnimation from '../../rendering/animation/KeysAnimation';
import { KeysPlayback } from 'jibo-cai-utils';
import { Playback } from 'jibo-anim-db';

enum animSelector {path = 1, pathFunction = 2, name = 3, query = 4}

/**
 * @class PlayAnimation
 * @extends jibo.bt.Behavior
 * @memberof jibo.bt.behaviors
 * @description Plays the animation specified by `animPath`, `animName` or `animQuery`.
 *              Succeeds when the animation is finished playing. Playing an
 *              animation consists of two phases: the transition phase and the play phase. The transition phase will
 *              transition Jibo from his current position to the start position of the specified animation. The play
 *              phase plays the animation with the current configuration.
 * @param {Object} options See {@link jibo.bt.Behavior|Behavior} for all options.
 * @param {String} options.animPath The path to the `.keys` file. This behavior assumes `${project}/animations` is the root for
 *                          all the animations.
 * @param {Function} options.config Called and passed a {@link AnimationBuilder} object for configuration purposes. Do not call
 *                          {@link AnimationBuilder#play}. This is done automatically by the behavior.
 * @param {Boolean} [options.cache=true] `true` to cache the animation. `false` to play once and destroy.
 */
export default class PlayAnimation extends Behavior {
    private alias:string;
    private animation:KeysAnimation;
    private instance:any|KeysPlayback;
    private status:Status;
    private cache:boolean;
    private stoppedCallbacks:Function[] = [];
    private hasBeenReset: boolean;
    private animSelector: animSelector;
    private anim: any;

    // The existing "filename-based" code-path is retained, with new code-paths
    // added to handle AnimDB-based queries.

    constructor(options) {
        super(options);

        this.status = Status.INVALID;

        // Reference to the builder
        this.animation = null;
        this.instance = null;
        this.cache = null;

        // Bound function
        this.onEvent = this.onEvent.bind(this);
        this.animDBonEvent = this.animDBonEvent.bind(this);
        this.onStopped = this.onStopped.bind(this);

        //backward support for activities that have no animation "type selector"
        if (typeof this.options.animSelector === 'undefined') {
            this.options.animSelector = animSelector.path;
        }

        this.animSelector = this.options.animSelector;
        switch (this.animSelector) {
            case animSelector.path:
                this._constructorFromPath(options);
                break;
            case animSelector.pathFunction:
                this._constructorFromPath(options);
                break;
            case animSelector.name:
                this._constructorFromAnimName(options);
                break;
            case animSelector.query:
                this._constructorFromAnimQuery(options);
                break;
        }
    }

    // Filename-based playback
    _constructorFromPath(options) {
        if (typeof this.options.cache === 'undefined') {
            this.options.cache = true;
        }

        //backward support
        if (typeof this.options.upload === 'undefined') {
            this.options.upload = true;
        }

        let animPath = this.animSelector === animSelector.path ? this.options.animPath : this.options.animPathFunction();

        //first default this asset to the 'animations' folder
        this.alias = PathUtils.setDefaultPath('animations', animPath);
        this.cache = this.options.cache;
    }

    // AnimDB-based playback (name and query-based).
    _constructorFromAnimName(options) {
        this.anim = Runtime.instance.animDB.getAnimByName(this.options.animName);
    }

    _constructorFromAnimQuery(options) {
        let results = Runtime.instance.animDB.query(this.options.queryParams());
        this.anim = this.options.queryResultSelector(results);
    }

    start(): boolean {
        this.hasBeenReset = false;
        this.status = Status.IN_PROGRESS;

        switch (this.animSelector) {
            case animSelector.path: return this._startFromPath();
            case animSelector.pathFunction: return this._startFromPath();
            default:
                if (!this.anim) {
                    // Handle the case where an AnimDB name or query lookup fails.
                    this.status = Status.FAILED;
                    return false;
                }
                this._startFromAnimDB();
                return true;
        }
    }

    _startFromPath() {
        let animation = Runtime.instance.loader.cached(this.alias);

        // Don't reload the animation, it's already cached
        if (this.cache && animation) {
            animation = animation.getCleanCopy();
            this.onKeysLoaded(null, animation);
        }
        // Load the animation
        else {
            const src = PathUtils.getAssetUri(this.alias, this.assetPack);
            Runtime.instance.loader.load({
                id: this.alias,
                cache: true,
                src: src,
                upload: this.options.upload,
                root: PathUtils.findRoot(src),
                type: 'keys',
                complete: this.onKeysLoaded.bind(this)
            });
        }
        return true;
    }

    async _startFromAnimDB():Promise<void> {
        try {
            const playback:Playback = await this.anim.createFromConfig(this.options.creationOptions());
            const keysPlayback = await playback.init();
            if (this.status !== Status.IN_PROGRESS) {
                keysPlayback.stop();
            }
            else {
                keysPlayback.on('EVENT', this.animDBonEvent);
                this.instance = keysPlayback;
                await playback.play(this.options.playbackOptions());
                this.onStopped();
            }
        }
        catch(e) {
            throw e;
        }
    }

    update() {
        return this.status;
    }

    stop():Promise<void> {
        if (this.instance) {
            return new Promise<void>((resolve) => {
                this.stoppedCallbacks.push(resolve);
                this.instance.stop();
            });
        }
        else {
            this.reset();
            return Promise.resolve();
        }
    }

    destroy() {
        this.reset();
        super.destroy();
        this.onEvent = null;
        this.onStopped = null;
        this.status = null;
        this.stoppedCallbacks = null;
    }

    private onKeysLoaded(err, animation) {
        if (err) {
            throw err;
        }
        //if status is not in progress, then behavior was stopped or destroyed
        if (this.status !== Status.IN_PROGRESS) {
            if (!this.cache) {
                Runtime.instance.loader.unload(this.alias);
            }
            return;
        }
        // Add the animation to the face
        this.animation = Runtime.instance.face.eye.animation = animation;

        // Listen for stopped event
        this.animation.on(KeysAnimation.STOPPED, this.onStopped);

        // Listen for cancelled event
        this.animation.on(KeysAnimation.CANCELLED, this.onStopped);

        // register for all events
        this.animation.on(KeysAnimation.EVENT, this.onEvent);

        if (this.options.config) {
            this.options.config(this.animation);
        }
        this.instance = Runtime.instance.dofArbiter.playAnimation(this.animation.builder, 'Behavior');
    }

    private reset() {
        if (this.hasBeenReset) {
            return;
        }

        if (this.animation) {
            Runtime.instance.face.eye.animation = null;

            if (this.animation.isCopy) {
                this.animation.destroy();
            }
            else {
                this.animation.removeAllListeners();
            }
        }
        this.animation = null;
        this.instance = null;
        if (!this.cache &&
            (this.animSelector === animSelector.path ||
             this.animSelector === animSelector.pathFunction)) {
            Runtime.instance.loader.unload(this.alias);
        }
        this.hasBeenReset = true;
    }

    private onStopped() {
        this.reset();
        this.status = Status.SUCCEEDED;
        for (let i = 0; i < this.stoppedCallbacks.length; i++) {
            this.stoppedCallbacks[i]();
        }
        this.stoppedCallbacks = [];
    }

    private onEvent(extra, animInstance, payload) {
        Runtime.instance.behaviorEmitter.emit(
            payload.eventName,
            animInstance,
            payload.payload
        );
    }

    private animDBonEvent(animInstance, payload) {
        Runtime.instance.behaviorEmitter.emit(
            payload.eventName,
            animInstance,
            payload.payload
        );
    }
}
