import Runtime from '../../../Runtime';

/**
 * Interface describing data that is attached to each MIM analytics event.
 * @private
 */
export interface AnalyticsBase {
    mim_type:string;
    mim_id:string;
    interaction_id:string;
};

/**
 * Enum for different ways that MIMs can exit
 * @private
 */
export const EXIT_TYPE = {
    INTERRUPT: 'interruption',
    SUCCESS: 'success',
    MAX_NI: 'max_no_input',
    MAX_NM: 'max_no_match'
};

/**
 * Enum for states in which the MIM could be interrupted (that we care about)
 * @private
 */
export const INTERRUPT_STATE = {
    SPEECH: 'speech',
    LISTEN: 'listen'
};

/**
 * Enum for different methods of input for MIMs
 * @private
 */
export const INPUT = {
    SPEECH: 'speech',
    TOUCH: 'touch',
    SILENCE: 'silence'
};

/**
 * Sends analytics event for the end of a MIM
 * @private
 */
export function end(base:AnalyticsBase, exit_type:string, input_type:string, intent_selected:string, interruption_state = '') {
    Runtime.instance.analytics.track('Mim End', Object.assign(
        {
            exit_type,
            input_type: input_type || '',
            intent_selected: intent_selected || '',
            interruption_state
        }, base));
}

/**
 * Sends analytics event for the beginning of a MIM
 * @private
 */
export function launch(base:AnalyticsBase) {
    Runtime.instance.analytics.track('Mim Launch', Object.assign({}, base));
}

/**
 * Sends analytics event for a user response that does not end the MIM (like thanks/repeat)
 * @private
 */
export function nonEndingResult(base:AnalyticsBase, input_type:string, intent:string, domain:string, prev_prompt:string) {
    Runtime.instance.analytics.track('Mim Non-ending Result', Object.assign(
        {
            input_type,
            intent,
            domain,
            prev_prompt
        }, base));
}

/**
 * Sends analytics event for a user response that wouldn't end the MIM, but it isn't being handled for some reason
 * @private
 */
export function nonEndingIgnored(base:AnalyticsBase, input_type:string, intent:string, domain:string, prev_prompt:string) {
    Runtime.instance.analytics.track('Mim Non-ending Ignored', Object.assign(
        {
            input_type,
            intent,
            domain,
            prev_prompt
        }, base));
}

/**
 * Sends analytics event for a No Match error
 * @private
 */
export function noMatch(base:AnalyticsBase, error_count:number, prev_prompt:string) {
    Runtime.instance.analytics.track('Mim No Match', Object.assign(
        {
            error_count,
            prev_prompt
        }, base));
}

/**
 * Sends analytics event for a No Input error
 * @private
 */
export function noInput(base:AnalyticsBase, error_count:number, prev_prompt:string) {
    Runtime.instance.analytics.track('Mim No Input', Object.assign(
        {
            error_count,
            prev_prompt
        }, base));
}