import {Event, EventContainer} from 'jibo-typed-events';
import {Sector} from 'jibo-common-types';
import * as async from 'async';
import { WSClient } from 'jibo-client-framework';
import IdentityService from "./id";
import Runtime from "../Runtime";

/**
 * Callback for LPS Service
 * @callback jibo.lps~Callback
 * @param [err] {String | Error} String of error text, or null if success.
 * @param [data] {any} Data of successful call. Varies by function.
 */
declare type Callback = (err?: string|Error, data?:any) => void;

/**
 * @description
 * Local Perceptual Space Events
 * Events that are emitted upon data received.
 * Example usage:
 * ```
 * jibo.lps.events.audio.on(data => {
 *   console.log(data.entities.length);
 * });
 * ```
 * @namespace jibo.lps.events
 */
export class LPSEvents extends EventContainer {

    /**
     * Emits an event when new audio data is received from service.
     * @name jibo.lps.events#audio
     * @type {Event}
     */
    audio = new Event<any>('LPS Audio Event');
    /**
     * Emits an event when new motion data is received from service.
     * @name jibo.lps.events#motion
     * @type {Event}
     */
    motion = new Event<any>('LPS Motion Event');
}

/**
 * @description
 * Local Perceptual Space
 *
 * @namespace jibo.lps
 */
class LPSService {
    public events: LPSEvents;
    public identity: IdentityService;
    private lps:any;
    private httpUrl: string;
    private lpsServiceUrl: string;
    private motionSocket:WSClient;
    private audioSocket:WSClient;
    /**
     * Queue of callbacks for calling demandDetect
     * @name jibo.lps~demandDetectQueue
     * @type {Array<Callback>}
     * @private
     */
    private _demandDetectQueue: Callback[];
    /**
     * Keeps track of whether a demandDetect call sets redirect
     * @name jibo.lps~_demandDetectRedetect
     * @type {Boolean}
     * @private
     */
    private _demandDetectRedetect: boolean;
    /**
     * Lighting quality around jibo's cameras
     * @name jibo.lps~_lightingQuality
     * @type {number}
     * @private
     */
    private _lightingQuality:number;
    /**
     * Lighting level around jibo's cameras
     * @name jibo.lps~_lightingLevel
     * @type {number}
     * @private
     */
    private _lightingLevel:number;
    /**
     * Sectors of Jibo's LPS, sorted by visibility
     * @name jibo.lps~_sectors
     * @type {Sector[]}
     * @private
     */
    private _sectors:Sector[];

    constructor() {
        this.lps = {};

        // visual awareness data
        this.lps.motionData = {
            cameras: [],    // List of camera objects
            entities: [],    // List of entity objects
            ts: [0,0]
        };
        // audible awareness data
        this.lps.audioData = {
            entities: [],    // List of entity objects
            ts: [0,0]
        };
        this._demandDetectQueue = [];
        this.identity = new IdentityService(this);
        this.events = new LPSEvents();
        this._sectors = [];
    }

    /**
     * Return the full state of the Jibo's local perceptual space.
     * @name jibo.lps#motionData
     * @type {*|{cameras: Array, entities: Array}}
     * @readOnly
     */
    get motionData() {
        return this.lps.motionData;
    }
    /**
     * Return the full audio state of the Jibo's local perceptual space.
     * @name jibo.lps#audioData
     * @type {any}
     * @readOnly
     */
    get audioData() {
        return this.lps.audioData;
    }

    /**
     * Get recent lighting quality for jibo's cameras as averaged by 3 most visible sectors.
     * [0,1] with 1 being highest quality, 0 being lowest.
     * WARNING: for best results, must be used with platform >=5.1.0
     * @name jibo.lps#lightingQuality
     * @type {number}
     */
    public get lightingQuality():number {
        return this._lightingQuality;
    }

    /**
     * Get recent lighting level for jibo's cameras as averaged by 3 most visible sectors.
     * [0,1] with 1 being highest lighting level, 0 being lowest.
     * WARNING: for best results, must be used with platform >=5.1.0
     * @name jibo.lps#lightingLevel
     * @type {number}
     */
    public get lightingLevel():number {
        return this._lightingLevel;
    }

    /**
     * Get the visual entity closest to Jibo.
     * @method jibo.lps#getClosestVisualEntity
     *
     * @return The closest visual entity to Jibo. If one does not exist, returns undefined.
     */
    getClosestVisualEntity() {
        let entity;

        if (this.lps.motionData !== undefined &&
            this.lps.motionData.entities !== undefined &&
            this.lps.motionData.entities.length > 0) {
            entity = this.lps.motionData.entities[0]; // @TODO - get real "closest" entity when multi-track is in
        }

        return entity;
    }

    /**
     * Get a visual entity by specified ID.
     * @method jibo.lps#getVisualEntityById
     * @param id {Number} ID of the entity to get.
     * @return The specified visual entity. If it does not exist, returns undefined.
     */
    getVisualEntityById(id) {
        let entity;

        for (let i=0; i< this.lps.motionData.entities.length; i++)
        {
            let itr = this.lps.motionData.entities[i];
            if (itr && (itr.id === id)) {
                entity = itr;
                break;
            }
        }

        return entity;
    }

    /**
     * Get the closest audible entity to Jibo.
     * @method jibo.lps#getClosestAudibleEntity
     *
     * @return The closest audible entity to Jibo. If one does not exist, returns undefined.
     */
    getClosestAudibleEntity() {
        let entity;

        if (this.lps.audioData !== undefined &&
            this.lps.audioData.entities !== undefined &&
            this.lps.audioData.entities.length > 0) {
            entity = this.lps.audioData.entities[0]; // @TODO - get real "closest" entity when multi-track is in
        }

        return entity;
    }

    /**
     * Get an audible entity by specified ID.
     * @method jibo.lps#getAudibleEntityById
     * @param id {Number} ID of the entity to get.
     * @return The specified audible entity. If it does not exist, returns undefined.
     */
    getAudibleEntityById(id) {
        let entity;

        for (let i=0; i< this.lps.audioData.entities.length; i++)
        {
            let itr = this.lps.audioData.entities[i];
            if (itr && (itr.id === id)) {
                entity = itr;
                break;
            }
        }

        return entity;
    }

    /**
     * Create new entry in LPS identity list.
     * @method jibo.lps#createIdentity
     * @param data {Object} Options for the request.
     * @param data.name {String} Name for the identity.
     * @param [data.kind="face"] {String} Kind of identity data. (Currently ONLY supports "face".)
     * @param cb {Function} Callback for the method.
     * @private
     */
    createIdentity(data, cb){
        const identityServiceUrl = this._getIdentityServiceUrl();
        // on plat builds 3.0.X, separate identity service.
        // this maintains backwards compatibility
        if(identityServiceUrl) {
            this._sendIdentityRequest('/identity/create', data, identityServiceUrl, cb);
        }
        else {
            this._sendIdentityRequest('/lps/identity/create', data, this.httpUrl, cb);
        }
    }

    /**
     * Remove entry from LPS identity list.
     * @method jibo.lps#removeIdentity
     * @param data {Object} Options for the request.
     * @param data.name {String} Name for the identity.
     * @param [data.kind="face"] {String} Kind of identity data. (Currently ONLY supports "face".)
     * @param cb {jibo.lps~Callback} Callback for the method.
     * @private
     */
    removeIdentity(data, cb:Callback){
        const identityServiceUrl = this._getIdentityServiceUrl();
        // on plat builds 3.0.X, separate identity service.
        // this maintains backwards compatibility
        if(identityServiceUrl) {
            this._sendIdentityRequest('/identity/remove', data, identityServiceUrl, cb);
        }
        else {
            this._sendIdentityRequest('/lps/identity/remove', data, this.httpUrl, cb);
        }
    }

    /**
     * Get the Identity service Url
     * @method jibo.lps#removeIdentity
     * @param data {Object} Options for the request.
     * @param data.name {String} Name for the identity.
     * @param [data.kind="face"] {String} Kind of identity data. (Currently ONLY supports "face".)
     * @param cb {Function} Callback for the method.
     * @private
     */
    _getIdentityServiceUrl():string {
        let serviceHost:string;
        let servicePort:number;
        // forEach is a blocking process, so we are guaranteed to
        // go through each member of the array before returning.
        Runtime.instance.records.forEach((record) => {
            if (record.name === "identity") {
                serviceHost = record.host;
                servicePort = record.port;
            }
        });
        return serviceHost ? "http://" + serviceHost + ":" + servicePort : null;
    }

    /**
     * Set up new training request. Request LPS to train an identified for a name using current sensor data.
     * @method jibo.lps#sendTrainingRequest
     * @param data {Object} Options for the training request.
     * @param data.name {String} Name for the training data.
     * @param [data.kind="face"] {String} Kind of data to be trained on. (Currently ONLY supports "face".)
     * @param cb {jibo.lps~Callback} Callback for the method.
     * @private
     */
    sendTrainingRequest(data, cb:Callback){
        const path = '/lps/identity/train';
        this._sendIdentityRequest(path, data, this.httpUrl, cb);
    }

    _sendIdentityRequest(path, data, httpUrl, cb) {
        if (httpUrl === undefined) {
            cb('Identity service is not initialized', null);
            return;
        }

        let params:any = {};

        if(!data) {
            cb(`cannot send identity request with ${data}`);
            return;
        }

        // name is a required parameter - if not present, return immediately
        if (!data.hasOwnProperty('name')){
            cb("Identity data must have 'name' property", null);
            return;
        }

        // these are NOT required parameters - if not present, use defaults
        if (!data.hasOwnProperty('kind')){ data.kind = "face";}

        params.name = data.name;
        params.kind = data.kind;

        let request = new XMLHttpRequest();
        request.open("POST", httpUrl + path, true);
        request.onreadystatechange = () => {
            if (request.readyState === 4) {
                if (request.status >= 200 && request.status <= 299) {
                    cb();
                }
                else {
                    // failure if anything else
                    let msg = 'Identity service unavailable';
                    if(request.statusText !== undefined && request.statusText !== "") {
                        msg = request.statusText;
                    }

                    // console.log("lps " + path + " response");
                    // console.log(request);

                    let errorData = null;
                    if (request.response) {
                        try {
                            errorData = JSON.parse(request.response);
                        }
                        catch (e) {
                            errorData = 'Response is not JSON.';
                        }
                    }

                    cb(msg, errorData);
                }
            }
        };
        request.send(JSON.stringify(params));
    }

    /**
     * Forces a one-shot full frame face detection and reports all faces detected
     * @param {number} cameraID ID for camera to be used.
     * @param {jibo.lps~Callback} cb Callback for the function which returns parsed data.
     * @param {string} [kind=faces] Kind of entities to search for.
     * @param {boolean} [initTracks=false] Hint to try to init the face ids which are tracked.
     * @method jibo.lps#getFaces
     */
    getFaces(cameraID:number, cb:Callback, kind:string, initTracks:boolean) {
        if (this.httpUrl === undefined) {
            cb('Identity service is not initialized', null);
            return;
        }

        let params: any = {};
        params.camera_id = cameraID;
        params.kind = kind;               // defaults in LPS Service; ok undefined here.
        params.init_tracks = initTracks;  // defaults in LPS Service; ok undefined here.

        let request = new XMLHttpRequest();
        request.open("POST", this.httpUrl + '/lps/faces', true);
        request.onreadystatechange = () => {
            if (request.readyState === 4) {
                if (request.status >= 200 && request.status <= 299) {
                    try {
                        const data = JSON.parse(request.response);
                        cb(null, data);
                    }
                    catch (e) {
                        const errorData = 'Response is not JSON.';
                        cb(errorData, null);
                    }
                }
                else {
                    // failure if anything else
                    let msg = 'LPS service unavailable:';
                    if (request.statusText !== undefined && request.statusText !== "") {
                        msg += request.statusText;
                    }

                    let errorData = null;
                    if (request.response) {
                        try {
                            errorData = JSON.parse(request.response);
                        }
                        catch (e) {
                            errorData = 'Response is not JSON.';
                        }
                    }

                    cb(msg, errorData);
                }
            }
        };
        request.send(JSON.stringify(params));
    }

    /**
     * Force the LPS to run face detection on jibo's present field of vision.
     * @param cameraID=0 {Number} (0|1) ID of Camera to run algorithm on.
     * @param redetect=false {Boolean} Should redetect (rerun algorithm) until a face is detected.
     * @param cb {jibo.lps~Callback} Callback with null error if detection algorithm ran, error otherwise. Results from face detection will only be represented through {@link jibo.lps#motionData}.
     * @method jibo.lps#demandDetect
     */
    demandDetect(cameraID:number, redetect:boolean, cb:Callback) {
        // already listening, just add to callback queue
        if(!!this._demandDetectQueue.length) {
            // if the call is with the same redetect parameter
            if(this._demandDetectRedetect === redetect) {
                this._demandDetectQueue.push(cb);
                return;
            }
            else {
                cb('Cannot Demand Detect while call with redetect:' + this._demandDetectRedetect + ' is in progress', null);
                return;
            }
        }

        // Since we don't have a call in progress, we can clobber
        // whatever our previous redetect was.
        this._demandDetectRedetect = redetect;
        this._demandDetectQueue.push(cb);

        if (this.httpUrl === undefined) {
            this._clearDemandDetectCallbacks('LPS service is not initialized', null);
            return;
        }

        const data = {
            'camera_id': cameraID,
            'roi': {
                'left': 0,
                'top': 0,
                'right': 640,
                'bottom': 360
            },
            'redetect': redetect
        };

        const request = new XMLHttpRequest();
        request.open('POST', this.httpUrl + '/lps/demand_detect', true);

        request.onreadystatechange = () => {
            if (request.readyState === 4) {
                // we're no longer waiting for a request response, reset class var
                if (request.status >= 200 && request.status <= 299) {
                    if (request.response) {
                        // success!
                        let response:any = {};
                        try {
                            response = JSON.parse(request.response);
                            this._clearDemandDetectCallbacks(null, response.detections);
                        }
                        catch (e) {
                            cb(e, null);
                        }
                    }
                    else {
                        this._clearDemandDetectCallbacks('No data received from LPS demand detection', null);
                    }
                }
                else {
                    // failure if anything else
                    let msg = 'Demand Detect failure:';
                    if(request.statusText !== undefined && request.statusText !== '') {
                        msg += request.statusText;
                    }

                    this._clearDemandDetectCallbacks(msg, null);
                }
            }
        };
        request.send(JSON.stringify(data));
    }

    /**
     * Call and clear all demand detect callbacks with error, data
     * @method jibo.lps~_clearDemandDetectCallbacks
     * @param err {Error | string} Error to call callbacks with.
     * @param data {any} Data to call callbacks with
     * @private
     */
    _clearDemandDetectCallbacks(err: string | Error, data: any) {
        this._demandDetectQueue.forEach((callback) => {
            callback(err, data);
        });
        this._demandDetectQueue = [];
    }


    /**
     * @description Barcode data object.
     * @typedef {Object} jibo.lps~BarcodeData
     * @property {int} type `0` (EAN8), `1` (UPCE), `2` (ISBN10), `3` (UPCA), `4` (EAN13), `5` (ISBN13),
     * `6` (Interleaved 2 of 5), `7` (Code 39), `8` (PDF417), `9` (QR-Code), or `10` (Code 128).
     * @property {string} content Payload of the barcode data.
     */

    /**
     * Read barcorde or QR code data.
     * @method jibo.lps#readBarcode
     * @param {Function} cb Callback for the function.
     * @return {jibo.lps~BarcodeData} Barcode data object.
     */
    readBarcode(cb) {
        if (this.httpUrl === undefined) {
            cb('Barcode service is not initialized', null);
            return;
        }

        let request = new XMLHttpRequest();

        request.open("GET", this.httpUrl + '/lps/barcode', true);

        request.onreadystatechange = () => {
            if (request.readyState === 4) {
                if (request.status >= 200 && request.status <= 299) {
                    if (request.response) {
                        // success!
                        let response = JSON.parse(request.response);
                        cb(null, response.barcodes);
                    }
                    else {
                        cb('No data received from barcode service', null);
                    }
                }
                else {
                    // failure if anything else
                    let msg = 'Barcode service unavailable';
                    if(request.statusText !== undefined && request.statusText !== "") {
                        msg = request.statusText;
                    }

                    cb(msg, null);
                }
            }
        };

        request.send();
    }

    /**
     * Set a present person.
     * @method jibo.lps#setPresence
     * @param {jibo.lps.identity.PresenceRecord} presenceData Data to set around environment.
     * @param {Function} cb Callback for the function.
     */
    setPresence(presenceData, cb) {
        if (this.httpUrl === undefined) {
            cb('LPS Service is not initialized', null);
            return;
        }

        let request = new XMLHttpRequest();

        request.open("POST", this.httpUrl + '/lps/presence', true);

        request.onreadystatechange = () => {
            if (request.readyState === 4) {
                if (request.status >= 200 && request.status <= 299) {
                    if (request.response) {
                        // success!
                        const response = JSON.parse(request.response);
                        cb(null, response);
                    }
                    else {
                        cb('No data received from barcode service', null);
                    }
                }
                else {
                    // failure if anything else
                    let msg = 'Failed to set presence';
                    if(request.statusText !== undefined && request.statusText !== "") {
                        msg += request.statusText;
                    }

                    cb(msg, null);
                }
            }
        };

        request.send(JSON.stringify(presenceData));
    }

    init(service, cb) {
        this.lpsServiceUrl = "ws:" + service.host + ":" + service.port;
        this.httpUrl = "http://" + service.host + ":" + service.port;
        async.parallel(
            [
                this._createMotionSocket.bind(this),
                this._createAudioSocket.bind(this)
            ],
            cb
        );
        // remember to initialize the identity service!
        this.identity.init();
    }

    _createMotionSocket(cb) {
        this.motionSocket = new WSClient(this.lpsServiceUrl + "/lps/visual_awareness");

        this.motionSocket.on('error', (/*err*/) => {
            console.error(`Error opening visual awareness socket at ${this.lpsServiceUrl}/visual_awareness`);
        });
        // TODO: Type this data and rename this socket!
        this.motionSocket.on('message', (data) => {
            this.lps.motionData = data;
            this.events.motion.emit(data);
            // Guard against old versions of platform/sim
            if(data.awareness && data.awareness.sectors) {
                this._extractSectorInformation(data.awareness.sectors);
            }
        });

        cb();
    }

    _createAudioSocket(cb) {
        this.audioSocket = new WSClient(this.lpsServiceUrl + "/lps/audible_awareness");

        this.audioSocket.on('error', (/*err*/) => {
            console.error(`Error opening audible awareness socket at ${this.lpsServiceUrl}/audible_awareness`);
        });

        this.audioSocket.on('message', (data) => {
            this.lps.audioData = data;
            if (data.entities.length) {
                this.events.audio.emit(data);
            }
        });

        cb();
    }

    /**
     * Extract information about jibo's visible sectors
     * @method jibo.lps~_extractSectorInformatin
     * @param {jibo.lps.Sector[]} sectors Raw sector data from websocket.
     * @private
     */
    _extractSectorInformation(sectors:Sector[]) {
        // sort by visibility
        this._sectors = sectors;
        this._sectors.sort((sect1:Sector, sect2:Sector) => {
            // check for visibility property to maintain backwards compatibility
            if(sect1.visibility) {
                return sect2.visibility.value - sect1.visibility.value;
            }
        });
        // just avg top three
        this._lightingLevel = (this._sectors[0].lightingLevel.value +
                               this._sectors[1].lightingLevel.value +
                               this._sectors[2].lightingLevel.value) / 3;
        this._lightingQuality = (this._sectors[0].lightingQuality.value +
                                 this._sectors[1].lightingQuality.value +
                                 this._sectors[2].lightingQuality.value) / 3;
    }


}

export default LPSService;
