export function configurable(value: boolean):PropertyDecorator {
    return function (target: any, propertyKey: string) {
        let descriptor = Object.getOwnPropertyDescriptor(target, propertyKey);
        descriptor.configurable = value;
        Object.defineProperty(target, propertyKey, descriptor);
    };
}

export function writable(value: boolean):PropertyDecorator {
    return function (target: any, propertyKey: string) {
        let descriptor = Object.getOwnPropertyDescriptor(target, propertyKey);
        descriptor.writable = value;
        Object.defineProperty(target, propertyKey, descriptor);
    };
}

export function enumerable(value: boolean):PropertyDecorator {
    return function (target: any, propertyKey: string) {
        let descriptor = Object.getOwnPropertyDescriptor(target, propertyKey);
        descriptor.enumerable = value;
        Object.defineProperty(target, propertyKey, descriptor);
    };
}

export function constant(target: any, propertyKey: string) {
    let descriptor = Object.getOwnPropertyDescriptor(target, propertyKey);
    descriptor.writable = false;
    descriptor.configurable = false;
    Object.defineProperty(target, propertyKey, descriptor);
};


/** @isInitialized method decorator
 *
 * Enforces that `this.isInitialized` is true or calls the callback with an error.
 * Assumes the last argument is the callback. Must appear after @promisfy decorator, if any.
 * @internal
 */
export function isInitialized(target: Object, propertyKey: string, descriptor: TypedPropertyDescriptor<any>):any {
    let originalMethod = descriptor.value; // the original decorated method

    // don't use arrow syntax for this function
    // see http://stackoverflow.com/questions/29775830/how-to-implement-a-typescript-decorator
    descriptor.value = function() {
        let args = Array.from(arguments);
        if (!this.isInitialized) {
            // not inited, callback with an error
            let callback = args.slice(0, -1)[0];
            let err = new Error(`${this.constructor.name} class instance is not initialized`);
            callback(err);
            return undefined;
        } else {
            // call it normally
            return originalMethod.apply(this, args);  // run the decorated method
        };
    };
    return descriptor;
}


/** @promisify method decorator
 *
 * Assumes the last argument is suppose to be a callback.  If the last
 * argument isn't a function, then assume the callback was left off on
 * purpose and wrap the method call in a promise and return the
 * promise.
 *
 * Note: only works with callbacks that return one result (or less) in
 * addition to the err argument. e.g. callback(err), or callback(err, res),
 * but not callback(err, res, res2) (because of the way promises work)
 * @internal
 */
export function promisify(target: Object, propertyKey: string, descriptor: TypedPropertyDescriptor<any>):any {
    let originalMethod = descriptor.value; // the original decorated method

    // don't use arrow syntax for this function
    // see http://stackoverflow.com/questions/29775830/how-to-implement-a-typescript-decorator
    descriptor.value = function() {
        let result;
        let args = Array.from(arguments);
        let callbackArg = args[args.length-1];
                                       
        if (typeof callbackArg === 'function') {
            // callback given, just call it normally and we are done here
            result = originalMethod.apply(this, args);  // run the decorated method
        } else {
            // no callback, promisfy it
            result = new Promise( (resolve, reject) => {
                let callback = function(err, arg) {
                    if (err) {
                        reject(err);
                    } else {
                        resolve(arg);
                    }
                };
                let newArgs = args.concat(callback);
                originalMethod.apply(this, newArgs);  // run the decorated method
            });
        }
        return result;
    };

    return descriptor;
}


/** @promisify_n method decorator
 * Takes one argument, the argument number of the callback. If that
 * argument isn't a function, then assume the callback was left off on
 * purpose and wrap the method call in a promise and return the
 * promise.  The argument number is one-based: the first argument
 * number is 1 (not zero), the second argument is 2, etc.
 *
 * The decorator takes the argument just like a function:
 *   @promisify_n(2)  // if the second argument is the callback
 *
 * Note: only works with callbacks that return one result (or less) in
 * addition to the err argument. e.g. callback(err), or callback(err, res),
 * but not callback(err, res, res2) (because of the way promises work)
 * @internal
 */
export function promisify_n(argNum:number) {
    function doPromisify(target: Object, propertyKey: string, descriptor: TypedPropertyDescriptor<any>):any {
        let originalMethod = descriptor.value; // the original decorated method

        // don't use arrow syntax for this function
        // see http://stackoverflow.com/questions/29775830/how-to-implement-a-typescript-decorator
        descriptor.value = function() {
            let result;
            let args = Array.from(arguments);
            if (argNum < 1 || argNum > originalMethod.length) {
                throw new Error('promisify_n decorator given invalid argument number');
            }

            let callbackArg = args[argNum-1];
            if (typeof callbackArg === 'function') {
                // callback given, just call it normally and we are done here
                result = originalMethod.apply(this, args);  // run the decorated method
            } else {
                // no callback, promisfy it
                result = new Promise( (resolve, reject) => {
                    let callback = function(err, arg) {
                        if (err) {
                            reject(err);
                        } else {
                            resolve(arg);
                        }
                    };
                    let newArgs = args.slice(0, argNum-1).concat(callback).concat(args.slice(argNum-1));
                    originalMethod.apply(this, newArgs);  // run the decorated method
                });
            }
            return result;
        };

        return descriptor;
    }

    return doPromisify;
}
