import {Plugin, PluginCallback} from 'jibo-plugins';
import * as action from 'jibo-action-system';
import Runtime from '../Runtime';

/**
 * Installs the Action API, which can be found in the "jibo-action-system" module
 * @class ActionPlugin
 * @implements Plugin
 * @private
 */
class ActionPlugin implements Plugin {

    api = action.api;

    init(done:PluginCallback): void {
        const jibo = Runtime.instance;
        action.api.init({jibo})
            .then(() => done())
            .catch(e => done(e));
    }
}

// register it as a jibo plugin
Runtime.registerPlugin(ActionPlugin, 'action', {
    depends: ['anim-utils'],
    api: true,
    name: 'action'
});

export default ActionPlugin;
