import {Plugin, PluginCallback} from 'jibo-plugins';
import * as emotion from 'jibo-emotion-system';
import Runtime from '../Runtime';

/**
 * Installs the Emotion API, which can be found in the "jibo-emotion-system" module
 * @class Emotion
 * @implements Plugin
 * @private
 */
class EmotionPlugin implements Plugin {

    api = emotion.api;

    init(done:PluginCallback): void {
        const jibo = Runtime.instance;
        emotion.api.init({jibo: jibo})
            .then(() => done())
            .catch(e => done(e));
    }
}

// register it as a jibo plugin
Runtime.registerPlugin(EmotionPlugin, 'emotion', {
    depends: ['action'],
    api: true,
    name: 'emotion'
});

export default EmotionPlugin;