import Component from '../../Component';

/**
 * Abstract class for subcomponents that can be added to Components.
 * @class Subcomponent
 * @memberof jibo.face
 * @abstract
 * @intdocs
 */
abstract class Subcomponent {

    /**
     * Subcomponent identifier.
     * @name jibo.face.Subcomponent.TYPE
     * @type {String}
     * @default 'TouchInteractive'
     * @readOnly
     */
    public static get TYPE():string {return 'TouchInteractive';}

    /**
     * Type of Subcomponnet, used for identification
     * @name jibo.face.Subcomponent#type
     * @type {String}
     * @readOnly
     */
    public get type():string { return this._type; }

    /**
     * Owning Component.
     * @name jibo.face.Subcomponent.component
     * @type {Boolean}
     * @protected
     */
    protected component:Component = null;

    /**
     * Type of Subcomponent, used for mapping storage and retrieval.
     * @name jibo.face.Subcomponent._type
     * @type {String}
     * @private
     */
    private _type:string;

    constructor(type:string) {
        this._type = type;
    }

    /**
     * Initialize Subcomponent.
     * @method jibo.face.Subcomponent#init
     * @param {jibo.face.Component} component - Component this Subcomponent is being added to.
     */
    public init(component:Component):void {
        this.component = component;
    }

    /**
     * Destroy.
     * @method jibo.face.Subcomponent#destroy
     */
    public destroy():void {
        if(this.component){
            this.component = null;
        }
    }
}

export default Subcomponent;
