import {SensoryType} from "./DataTypes";
import {Clock, Time, Timestamp} from "animation-utilities";
import JiboLog = require("jibo-log");
import {SensoryRecord, PresenceRecord, SpeakerRecord} from "./LPSRecords";
import {IdentityEvents} from "./IDEvents";
import {SID_Status, LPSVisualEntityTypes, LPSEntity} from "jibo-common-types";
import { Event as TypedEvent } from 'jibo-typed-events';

/**
 * @description
 * Convert data from various raw forms into standardized SensoryRecords, extract relevant
 * data and events for skills.
 * @class DataConverter
 * @memberOf jibo.lps.identity
 * @intdocs
 */
export class DataConverter{

    /**
     * Events for IdentityService to listen to to emit public events.
     * @name jibo.lps.identity.DataConverter#events
     * @type {jibo.lps.identity.IdentityEvents}
     */
    public events:IdentityEvents;
    /**
     * Last speaker heard by LPS
     * @name jibo.lps.identity.DataConverter~_lastSpeaker
     * @type {jibo.lps.identity#SensoryRecord}
     * @private
     */
    private _lastSpeaker: SpeakerRecord;
    /**
     * Last time we heard Hey Jibo
     * @name jibo.lps.identity.DataConverter~_lastSpokeTime
     * @type {Time}
     * @private
     */
    private _lastSpokeTime: Time;
    /**
     * last time we got vision information
     * @name jibo.lps.identity.DataConverter~_lastVisionTimestamp
     * @type {Timestamp}
     * @private
     */
    private _lastVisionTimestamp:Timestamp = null;
    /**
     * Entities being tracked by LPS
     * @name jibo.lps.identity.DataConverter~_sensoryEntities
     * @type {Map<string, jibo.lps.identity#SensoryRecord>}
     * @private
     */
    private _sensoryEntities:Map<string, SensoryRecord> = null;
    /**
     * Last time we heard Hey Jibo, by LPS Timestamp
     * @name jibo.lps.identity.DataConverter~_lastSpokeTimestamp
     * @type {Timestamp}
     * @private
     */
    private _lastSpokeTimestamp: Timestamp;
    /**
     * Presences being tracked by LPS
     * @name jibo.lps.identity.DataConverter~_presences
     * @type {Map<string, jibo.lps.identity/PresenceRecord>}
     * @private
     */
    private _presences: Map<string, PresenceRecord>;
    /**
     * Recent speakers as designated by LPS
     * @name jibo.lps.identity.DataConverter~_recentSpeakers
     * @type {Map<string, jibo.lps.identity#SensoryRecord>}
     * @private
     */
    private _recentSpeakers: Map<string, SpeakerRecord>;
    /**
     * All entities currently in the FOV.
     * @name jibo.lps.identity.DataConverter~_entitiesInFob
     * @type {Map<string, jibo.lps.identity#VisibleEntityRecord>}
     * @private
     */
    private _entitiesInFov: Map<string, LPSEntity>;
    /**
     * Used to log output
     * @name jibo.lps.identity.DataConverter~log
     * @type {JiboLog}
     * @private
     */
    private log:JiboLog;

    /**
     * @param {IdentityEvents} events
     * @param {JiboLog} log
     * @constructor
     */
    constructor(events:IdentityEvents, log:JiboLog){
        this.events = events;
        this._presences = new Map<string, PresenceRecord>();
        this._sensoryEntities = new Map<string, SensoryRecord>();
        // TODO: make this real.. just playing?
        this._lastSpokeTimestamp = [0,0];
        this._lastSpokeTime = Clock.currentTime();
        this._recentSpeakers = new Map<string, SpeakerRecord>();
        this._entitiesInFov = new Map<string, LPSEntity>();
        this.log = log;
    }

    /**
     * Get the most recent speaker as calculated by the data converter
     * @name jibo.lps.identity.DataConverter#mostRecentSpeaker
     * @type {jibo.lps.identity.SensoryRecord}
     */
    public get mostRecentSpeaker():SpeakerRecord {
        return this._lastSpeaker;
    }

    public set mostRecentSpeaker(speaker:SpeakerRecord) {
        throw new Error('Cannot set most recent speaker external to ID module.');
    }

    /**
     * Get the last time somebody spoke.
     * @name jibo.lps.identity.DataConverter#lastSpokeTime
     * @type {jibo.animate.Time}
     */
    public get lastSpokeTime():Time {
        return this._lastSpokeTime;
    }

    public set lastSpokeTime(time:Time) {
        throw new Error('Cannot set last spoke time external to ID module.');
    }

    /**
     * All presences being tracked by LPS
     * @name jibo.lps.identity.DataConverter~presences
     * @type {Map<string, jibo.lps.identity/PresenceRecord>}
     * @private
     */
    public get presences():Map<string, PresenceRecord> {
        return this._presences;
    }

    public set presences(pres:Map<string, PresenceRecord>) {
        throw new Error('Cannot set presences.');
    }

    /**
     * All visible presences being tracked by LPS
     * @name jibo.lps.identity.DataConverter~visibleFaces
     * @type {Map<string, jibo.lps.identity/VisibleEntityRecord>}
     * @private
     */
    public get visibleFaces():Map<string, LPSEntity> {
        return this._entitiesInFov;
    }

    public set visibleFaces(pres:Map<string, LPSEntity>) {
        throw new Error('Cannot set presences.');
    }

    /**
     * All people entities being tracked by LPS
     * @name jibo.lps.identity.DataConverter~people
     * @type {Map<string, jibo.lps.identity#SensoryRecord>}
     * @private
     */
    public get people():Map<string, SensoryRecord> {
        let peopleEntities = new Map<string, SensoryRecord>();
        this._sensoryEntities.forEach((person:SensoryRecord, key:string) => {
            if(person.type === SensoryType.PERSON) {
                peopleEntities.set(key, person.raw.id_summary);
            }
        });
        return peopleEntities;
    }

    public set people(people:Map<string, SensoryRecord>) {
        throw new Error('Cannot set visible people.');
    }

    /**
     * @method jibo.lps.identity.DataConverter#acceptAwareness
     * @description Accept information through LPS Vision socket.
     * @param {any} data Raw data from LPS socket.
     */
    acceptAwareness(data:any) {
        let dataTimestamp:Timestamp = [data.ts[0], data.ts[1]];
        if(this._lastVisionTimestamp === null || !(this._lastVisionTimestamp[0] === dataTimestamp[0] &&
                                                   this._lastVisionTimestamp[1] === dataTimestamp[1])){
            this._lastVisionTimestamp = dataTimestamp;
            this._extractMostRecentSpeaker(data.recent_speakers);
            this._extractPresences(data.presence);
            this._extractEntities(data.entities);
        }
    }

    /**
     * @description Extract speaker ID information from raw GL data
     * @param {any} data Raw speaker ID data from GL Service
     * @method jibo.lps.identity.DataConverter#acceptSpeakerId
     */
    acceptSpeakerId(data:any) {
        // old speaker ID data; if we're not getting the speaker_id
        // object, we're also not compatible with this LPS Version.
        let speaker;
        if(!data.speaker_id) {
            speaker = data.speakers[0];
            if(!speaker) {
                speaker = new SpeakerRecord({});
            }
            // massaging the data from old formats.
            speaker.sid_status = data.status;
            speaker.id = speaker.speaker_id;
        }
        else {
            speaker = new SpeakerRecord(data.speaker_id[0]);
        }
        if(speaker.sid_status === SID_Status.ACCEPTED) {
            this._lastSpeaker = speaker;
        }
        else {
            // if our first speaker ID wasn't accepted, none of the others will be either.
            // a la Speaker ID contract
            this._lastSpeaker = null;
        }
        data.reason = LPSVisualEntityTypes.WAKE;
        this.log.info("presence started", speaker);
        this.events.presenceStarted.emit(speaker);
        this.events.idAcquired.emit(speaker);
    }

    /**
     * @description Extract entity information from raw LPS data
     * @param {any} entities Raw entity data from LPS Service
     * @method jibo.lps.identity.DataConverter~_extractEntities
     * @private
     */
    private _extractEntities(entities: any) {
        // update all entity tracks
        // // vei == visual entity index

        // get keys to store for seen entities
        let seenKeys = [];
        for(let vei = 0; vei < entities.length; vei++){
            // keep track of the keys we've seen
            seenKeys.push(entities[vei].id);
            // TODO: motion happens so much more; separate it?

            this._extractFOVEntities(entities[vei]);

            // this is a person track and we've seen them before
            if(this._sensoryEntities.has(entities[vei].id)) {
                this._sensoryEntities.get(entities[vei].id).update(entities[vei]);
            }
            // this is a person and we haven't seen them
            else {
                const sensoryType = SensoryType[entities[vei].description];
                this._sensoryEntities.set(entities[vei].id, new SensoryRecord(entities[vei], null, SensoryType[sensoryType], Clock.currentTime()));
            }
        }

        // go through and clear out the faces we haven't seen this round.
        this._clearEntities(seenKeys,
                            this._entitiesInFov,
                            this.events.visibleFaceStopped);
        this._clearEntities(seenKeys,
                            this._sensoryEntities,
                            this.events.presenceEnded);
    }

    /**
     * @description Checks if entity is in FOV entities list.
     * @param {any} entity Raw entity data from LPS
     * @method jibo.lps.identity.DataConverter~_extractFOVEntities
     * @private
     */
    private _extractFOVEntities(entity) {
        let entityLog = this._entitiesInFov.get(entity.id);
        // we're already tracking this entity
        if(entityLog) {
            this._entitiesInFov.set(entity.id, <LPSEntity>entity);
        }
        else {
            if(entity.description === LPSVisualEntityTypes.PERSON &&
               entity.in_fov) {
                this._entitiesInFov.set(entity.id, <LPSEntity>entity);
                this.events.visibleFaceStarted.emit(entity);
            }
        }
    }

    /**
     * @description Clears entities if they disappeared from list.
     * @param {string[]} seenEntityIds Entity Ids we saw this update
     * @param {Map<any,any>} diffSet The set to compare against
     * @param {any} [event] Event to emit if a comparison is found.
     * @param {boolean} [condition] Any potential condition on which the event should be emitted.
     * @method jibo.lps.identity.DataConverter~_clearEntities
     * @private
     */
    private _clearEntities(seenEntityIds:string[], diffSet:Map<any,any>, event?:TypedEvent<any>) {
        diffSet.forEach((value, key) => {
            // key was in our set, but not in our seen entity IDs.
            // indicating that entity is no longer being "seen" by LPS.
            if(seenEntityIds.indexOf(key) < 0) {
                // Keeping a reference to entity so we may use it
                // when we emit an event after having removed it from the set
                const entityRef = diffSet.get(key);
                diffSet.delete(key);
                if(event) {
                    event.emit(entityRef);
                }
            }
        });
    }

    /**
     * @description Extract presence information from raw LPS data
     * @param {any} presences Raw presence data from LPS Service
     * @method jibo.lps.identity.DataConverter~_extractPresences
     * @private
     */
    private _extractPresences(presences: any) {
        // we didn't get any presences OR that AND we thought we had some!
        if((!presences || !presences.presence || (!presences.presence.length) && this._presences.size !== 0)) {
            // Clear out all presences, we don't think anybody is around
            this._presences.forEach((presence: PresenceRecord) => {
                this.log.info("presence ended", presence);
                this.events.presenceEnded.emit(presence);
            });
            this._presences.clear();
            return;
        }
        // we have some presences!
        const pres = presences.presence;
        for(let pi = 0; pi < pres.length; pi++) {
            // it's a set so we don't worry about duping.
            // also, all presences are necessarily people

            // we did not have this person present previously
            if(!this._presences.has(pres[pi].name)) {
                this.log.info("Adding a new presence ", pres[pi].name);
                // we previously had no presences, time to fire an event.
                if(this._presences.size === 0) {
                    this.log.info("presence started", pres[pi]);
                    this.events.presenceStarted.emit(pres[pi]);
                }
                this.log.info("ID Acquired", pres[pi].name);
                this.events.idAcquired.emit(pres[pi]);
                this._presences.set(pres[pi].name, new PresenceRecord(pres[pi]));
            }
            // update all the known presences we have by name.
            this._presences.get(pres[pi].name).update(pres[pi]);
        }
    }

    /**
     * @description Extract and calculate most recent speaker.
     * @param {any} speakers Raw speaker data from LPS Service
     * @method jibo.lps.identity.DataConverter~_extractMostRecentSpeaker
     * @private
     */
    private _extractMostRecentSpeaker(speakers:any) {
        // for some reason didn't get recent_speakers from LPS Service
        // or there were no recent speakers
        if(!speakers || !speakers.length) {
            return;
        }
        // speakers come in chronologically, recent is last
        speakers.reverse();
        let speaker = this._recentSpeakers.get(speakers[0].id);
        if(speaker) {
            this._recentSpeakers.get(speaker.id).update(speakers[0]);
        }
        // We haven't seen, let's add them.
        else {
            // TODO: FIGURE OUT WHY THIS SOMETIMES FLOODS LOGS
            // this.log.info("Adding a new speaker", speakers[0].id);
            this._recentSpeakers.set(speakers[0].id, new SpeakerRecord(speakers[0]));
        }
    }
}
