    /**
     * Make a request of the ASR service.
     * @param uriStub {String} the requested ASR method e.g. "/language", "/resume", etc.
     * @param callback {jibo.gl~Callback} Callback with response from GLService.
     * @param [payload] {Object} data to accompany the given method request (will be JSON.stringified).
     * @param [success] {function} returns a boolean indicating whether response was a
     * success (default: `(response) => response.status === 'OK'`).
     * @param [errorInfo] {function} returns the information from the response to
     * use as the err value of the callback if the response is not
     * success (default: `(response) => response.moreinfo`)
     * @private
     */

    public _makeRequest(uriStub:string, callback:Callback, payload?:any, success?:any, errorInfo?:any):void {
        let request = new XMLHttpRequest();
        request.open("POST", this.httpInterface + uriStub, true);

        if(callback) {
            if (!success) {
                success = (response) => response.status === 'OK';
            }
            if (!errorInfo) {
                errorInfo = (response) => response.moreinfo;
            }
            request.onreadystatechange = () => {
                if (request.readyState === 4 && request.status === 200) {
                    let response = JSON.parse(request.response);
                    if (success(response)) {
                        callback(null, response);
                    }
                    else {
                        console.log(`response to ${uriStub} failed`);
                        console.log(response);
                        callback(errorInfo(response));
                    }
                }
                else if(request.readyState === 4 && request.status === 0) {
                    callback("GLService is unavailable");
                }
            };
        }
        request.send(JSON.stringify(payload));
    }

    /**
     * Return `true `if string starts with Hey Jibo, `false` otherwise.
     * @param {word} word String to search for hey jibo.
     * @private
     */
    private startsWithHJ(word:string):boolean {
        word = word.trim().toLowerCase();
        if(word.substr(0, 8) === "hey jibo") {
            return true;
        }
        return false;
    }


    private processMessages():void {
        while(this.messages.length) {
            let msg:{data:WSResponse} = this.messages.shift();
            this.processNextMessage(msg);
        }
    }

    private processNextMessage(data:any):void {
        if(this.verbose) {
            console.log("GLSERVICE DATA", data);
        }
        if(data.status !== "OK") {
            console.warn("GLService returned status", data.status);
        }
        else {
            let handler = this.listenEventHandlers[data.message];
            if(handler) {
                handler(data);
            }
        }
    }

    /**
     * Called when ws with message 'cloud' is received.
     * @param {any} JSON Data received from websocket.
     * @method jibo.GLService#onCloud
     * @private
     */
    private onCloud(data:WSResponse) {
        // GLOBAL.jibo.AsrToEmitTimer.stop();
        // console.log(GLOBAL.jibo.AsrToEmitTimer.getTimings());
        Runtime.instance.performance.log('JiboCloudReturnSkill', data.result.result.Input);
        const listenData = new ListenResults(null, data.result.result, data.result.otherResults);
        if(data.id) {
            let listener = this._getListener(data.id);
            if(listener) {
                listener.events.cloudReceived.emit(listenData);
            }
            return;
        }
       this.events.cloudReceived.emit(listenData);
    }

