import {EventEmitter} from 'events';
import {Event, EmitterMode} from 'jibo-typed-events';
import Runtime from '../../Runtime';
import MimRepeatManager from './MimRepeatManager';
import MimConfig from './MimConfig';
import {States} from './MimState';
import {PathUtils} from 'jibo-plugins';
import {Model, Node} from 'jibo-kb';
import fs = require('fs');
import path = require('path');

import GlobalListenDelegate from './delegates/GlobalListenDelegate';
import BasicSpeakDelegate from './delegates/BasicSpeakDelegate';

import {selectItem} from './WeightedRotation';

/*
 * Interface for how a listener instance is used by MIMs. All ListenDelegates must produce one of
 * these with their create() functions.
 */
export interface Listener {
    stop(unsubscribe?:boolean):void;
    on(type:string, callback:Function):void;
}

export type ListenModeOptions = 'NORMAL'|'OPTIONAL_RESPONSE'|'NO_BODY'|'UI';
interface ListenDelegate {
    cleanupHandler?: (done:(error?)=>void)=>void;
    setMode(mode:ListenModeOptions):void;
    create(options:any, rulePath:string):Listener;
    create(options:any, handle:{rule:string, type:'handle'}):Listener;
}
interface SpeakDelegate {
    speak(options:any):Promise<any>;
    stop():void;
}

export enum HJCompleteReason {
    HJ_ONLY,
    NO_MATCH,
    NON_INTERRUPTING
}

class SingletonEnforcer {}

/**
 * Singleton for hooking into the MIM system.
 * @namespace jibo.mim
 */
//NOTE: This is the only class in the MIM code that is exposed outside of the jibo module, and
//should be considered mostly internal to Jibo, with potentially a few development features.
class MimManager extends EventEmitter {
    private static _instance:MimManager;
    
    //exposing MimConfig at runtime - this is only intended to be for unit tests, which is why
    //the class itself is still documented as private
    public MimConfig = MimConfig;
    //documented at declaration of this enum
    public States = States;
    /**
     * The default listen delegate class, for extending to make more advanced delegates.
     * @name jibo.mim~GlobalListenDelegate
     * @type {jibo.mim.GlobalListener}
     * @private
     */
    public GlobalListenDelegate = GlobalListenDelegate;

    /**
     * End the currently active MIM.
     * @name jibo.mim#end
     * @type {Event}
     * @intdocs
     */
    public end:Event<any>;
    /**
     * Open the GUI for the currently active MIM.
     * @name jibo.mim#openGUI
     * @type {Event}
     * @intdocs
     */
    public openGUI:Event<void>;
    /**
     * In the currently active MIM, handle a spoofed utterance.
     * @name jibo.mim#handleSpeech
     * @type {Event}
     * @intdocs
     */
    public handleSpeech:Event<string>;
    /**
     * In the currently active MIM, respond to a 'hey jibo' happening. MIMs could listen to
     * GlobalListen directly, but getting events through here allows us to limit the event to
     * the currently active MIM, in case a MIM is running another MIM.
     * @name jibo.mim#heyJibo
     * @type {Event}
     * @private
     */
    public heyJibo:Event<void>;
    /**
     * In the currently active MIM, respond to the completion of a HJ event in which the MIM should
     * continue. This includes HJ Only, HJ No Match, and Non Interrupting Global events.
     * @name jibo.mim#heyJiboComplete
     * @type {Event}
     * @private
     */
    public heyJiboComplete:Event<HJCompleteReason>;
    /**
     * If a Hey Jibo event currently active. Used by MIMs to determine when they started during an
     * active HJ event.
     * @name jibo.mim#isHeyJiboActive
     * @type {boolean}
     * @private
     */
    public isHeyJiboActive:boolean = false;

    /**
     * If `true`, Question MIMs time out after the specfied `timeout` when run in the simulator.
     * If `false` (default), time out when `enter` key is pressed.
     * @name jibo.mim~timeoutIgnoresSimulator
     * @type {Boolean}
     */
    public timeoutIgnoresSimulator:boolean = false;

    /**
     * MimRepeatManager instance with loaded MIM data.
     * @name jibo.mim~repeat
     * @type {jibo.mim.MimRepeatManager}
     * @private
     */
    public repeat: MimRepeatManager;

    /**
     * Promise to load MIM data used by all MIMs as global prompts.
     * @name jibo.mim~globalMimLoad
     * @type {Promise<void>}
     * @private
     */
    public globalMimLoad:Promise<void>;

    /**
     * MIM data used by potentially all MIMs as response to the 'thanks' MIM global.
     * @name jibo.mim~thanksResponse
     * @type {jibo.mim.MimConfig}
     * @private
     */
    public thanksResponse:MimConfig;

    /**
     * MIM data used by all MIMs as response to the 'what can i do' global.
     * @name jibo.mim~whatCanIDo
     * @type {jibo.mim.MimConfig}
     * @private
     */
    public whatCanIDo: MimConfig;

    //internal, not for general use
    public ListenMode:{NORMAL:'NORMAL', OPTIONAL_RESPONSE:'OPTIONAL_RESPONSE', NO_BODY:'NO_BODY', UI:'UI'} = {
        NORMAL: 'NORMAL',
        OPTIONAL_RESPONSE: 'OPTIONAL_RESPONSE',
        NO_BODY: 'NO_BODY',
        UI: 'UI'
    };

    /**
     * Listen delegate to be used by all MIMs to handle listening.
     * @name jibo.mim~listenDelegate
     * @type {ListenDelegate}
     * @private
     */
    public listenDelegate:ListenDelegate;
    /**
     * Speaking delegate to be used by all MIMs to handle speech.
     * @name jibo.mim~speakDelegate
     * @type {SpeakDelegate}
     * @private
     */
    public speakDelegate:SpeakDelegate;
    
    /**
     * Root node of the KB model used to store prompt rotation info for MIMs within the `jibo`
     * module.
     * @name jibo.mim~jiboRotationNode
     * @type {jibo.kb.Node}
     * @private
     */
    public jiboRotationNode:Node;
    /**
     * KB Models for each skill. These are kept in memory, because it isn't that much memory, and
     * gives us slightly faster access when we use multiple MIMs from one skill. Also, right now
     * everything lives in one process that never shuts down, and it won't matter when we have
     * each skill in a separate process.
     * @name jibo.mim~kbModels
     * @type {Object.<string, jibo.kb.Model>}
     * @private
     */
    private kbModels:{[assetPack:string]:Model};
    
    //only exposed during unit tests - should pretend it doesn't exist
    private selectItem:typeof selectItem;

    constructor(enforcer:SingletonEnforcer) {
        super();
        this.listenDelegate = GlobalListenDelegate;
        this.speakDelegate = new BasicSpeakDelegate();
        
        this.kbModels = {};

        this.end = new Event<any>('End MIM');
        this.end.setMode(EmitterMode.LAST_HANDLER);
        this.openGUI = new Event<void>('Open MIM GUI');
        this.openGUI.setMode(EmitterMode.LAST_HANDLER);
        this.handleSpeech = new Event<string>('Handle Spoofed Utterance');
        this.handleSpeech.setMode(EmitterMode.LAST_HANDLER);
        this.heyJibo = new Event<void>('Hey Jibo Heard');
        this.heyJibo.setMode(EmitterMode.LAST_HANDLER);
        this.heyJiboComplete = new Event<HJCompleteReason>('Hey Jibo Completed');
        this.heyJiboComplete.setMode(EmitterMode.LAST_HANDLER);

        this.onHeyJiboHeard = this.onHeyJiboHeard.bind(this);
        this.onHJOnly = this.onHJOnly.bind(this);
        this.onHJNoMatch = this.onHJNoMatch.bind(this);
        this.onShortGlobal = this.onShortGlobal.bind(this);
        this.onHJEnd = this.onHJEnd.bind(this);
        //MimManager probably gets set up before GL, so we'll add a listener when the first MIM
        //wants to start listening - we don't care before then anyway
        const origHJOn = this.heyJibo.on;
        this.heyJibo.on = (handler) => {
            this.attachHJListeners();
            this.heyJibo.on = origHJOn;
            return this.heyJibo.on(handler);
        };
        
        //UNIT TEST ONLY
        if (Runtime.instance.runMode === Runtime.instance.RunMode.UNIT_TESTS) {
            this.selectItem = selectItem;
        }
    }

    public static get instance():MimManager {
        if (!MimManager._instance) {
            MimManager._instance = new MimManager(new SingletonEnforcer());
        }
        return MimManager._instance;
    }
    
    /**
     * Loads the root node of a KB slice specific to an asset pack, so that data about prompt
     * rotation can be persisted.
     * @method jibo.mim~loadMimKB
     * @param {string} assetPack The name of the skill/asset pack that the MIM is loaded from.
     * @return {Promise<jibo.kb.Node>} The root node for that asset pack.
     * @private
     */
    public loadMimKB(assetPack:string):Promise<Node> {
        //if the asset pack ends with the asset pack token, strip that off
        if (assetPack.endsWith('://')) {
            assetPack = assetPack.substring(0, assetPack.length - 3);
        }
        //as 'core' and 'jibo' mean the same thing, enforce that they are one value for us
        if (assetPack === 'core') {
            assetPack = 'jibo';
        }
        //if no asset pack, then belongs to currently running skill - have to read the name
        //out of the package.json
        if (!assetPack) {
            try {
                const skillJSON = JSON.parse(fs.readFileSync(path.resolve(process.cwd(), 'package.json'), 'utf8'));
                assetPack = skillJSON.name;
            } catch (e) {
                return Promise.reject(e) as Promise<any>;
            }
        }
        //sanitize the skill/asset pack name, because the KB has limitations on characters
        assetPack = assetPack.toLowerCase().replace(/[^a-z0-9\/_-]/g, '');
        //load up the appropriate model, making it if needed
        if (this.kbModels[assetPack]) {
            return this.kbModels[assetPack].loadRoot();
        }
        //get the full slice name
        const sliceName = assetPack === 'jibo ' ? '/jibo/mims' : `/skills/${assetPack}/mims`;
        //create the slice, return the root node of that slice
        return Runtime.instance.kb.createSlice(sliceName)
            .then(() => {
                const model = Runtime.instance.kb.createModel(sliceName);
                this.kbModels[assetPack] = model;
                return model.loadRoot();
            });
    }

    /**
     * Start loading any assets the Mims need. Called on creation of the first Mim. Mim does not
     * wait for asset load to complete before continuing.
     * @method jibo.mim~loadMimAssets
     * @private
     */
    public loadMimAssets() {
        if (!this.globalMimLoad) {
            //load thanks MIM
            const loadThanks = MimConfig.load(PathUtils.getAssetUri('core://mims/en-us/globals/ThanksResponse.mim'))
                .then((config) => {
                    this.thanksResponse = config;
                });
            const loadWhatCanIDo = MimConfig.load(PathUtils.getAssetUri('core://mims/en-us/globals/WhatCanIDo.mim'))
                .then((config) => {
                    this.whatCanIDo = config;
                });
            //load repeat stuff
            this.repeat = new MimRepeatManager();
            //load the model for prompt rotation
            const loadRotation = this.loadMimKB('jibo').then((node) => {
                this.jiboRotationNode = node;
            });
            //combine all the loads into one promise for tracking
            this.globalMimLoad = Promise.all([loadThanks, loadWhatCanIDo, this.repeat.init(), loadRotation]) as any;
        }
    };
    
    /**
     * Attach listeners for HJ and HJ ending events
     * @method jibo.mim~attachHJListeners
     * @private
     */
    private attachHJListeners() {
        const events = Runtime.instance.gl.events;
        events.hjHeard.on(this.onHeyJiboHeard);
        events.hjOnly.on(this.onHJOnly);
        events.noGlobalMatch.on(this.onHJNoMatch);
        events.nonInterruptingGlobal.on(this.onShortGlobal);
        //listening for the end of all listens should be the simplest way to handle this, and
        //shouldn't harm anything - we aren't emitting events in this listener, so we won't be
        //doubling up on events if hjOnly & listenFinished both go, for example
        events.listenFinished.on(this.onHJEnd);
    }

    /**
     * Callback for Hey Jibo events from the listening service.
     * @method jibo.mim~onHeyJiboHeard
     * @private
     */
    private onHeyJiboHeard() {
        this.isHeyJiboActive = true;
        this.heyJibo.emit();
    }
    
    /**
     * Listener for Hey Jibo Only events, for recovering from the MIM's waitForHJEnd state.
     * @method jibo.mim#onHJOnly
     * @private
     */
    private onHJOnly() {
        //on "hey jibo ........ <crickets>"
        this.isHeyJiboActive = false;
        this.heyJiboComplete.emit(HJCompleteReason.HJ_ONLY);
    }

    /**
     * Listener for Hey Jibo No Match events, for recovering from the MIM's waitForHJEnd state.
     * @method jibo.mim#onHJNoMatch
     * @private
     */
    private onHJNoMatch() {
        //on "hey jibo <word barf>"
        this.isHeyJiboActive = false;
        this.heyJiboComplete.emit(HJCompleteReason.NO_MATCH);
    }

    /**
     * Listener for Non Interrupting Global events, for recovering from the MIM's waitForHJEnd state.
     * @method jibo.mim#onShortGlobal
     * @private
     */
    private onShortGlobal() {
        //when a global is finished being handled in place - this could be something as small
        //as changing the volume, or larger like answering "No" to a question of "Are you sure you want to quit"
        this.isHeyJiboActive = false;
        this.heyJiboComplete.emit(HJCompleteReason.NON_INTERRUPTING);
    }
    
    /**
     * Listener for the end of HJ listens that don't allow a MIM to continue - skill relaunches,
     * interrupting globals, etc.
     * @method jibo.mim#onHJEnd
     * @private
     */
    private onHJEnd() {
        this.isHeyJiboActive = false;
    }
}

export default MimManager;
