import request = require('request');
import Runtime from '../../Runtime';
import {promisify} from '../../utils/decorators';
import MediaNode from './MediaNode';
import {ThumbnailType} from './Media';
export {ThumbnailType} from './Media';
import {MediaType} from './MediaManagerService';
import {Model} from 'jibo-kb';
import MediaModelEvents from './MediaModelEvents';
import {WSClient} from 'jibo-client-framework';

import Log = require('jibo-log');
const log = new Log('MediaModel');

interface ThumbnailsResponse {
    [name:string]:string;  // uuid for each thumbnail
}

interface StorePhotoResponse {
    id:string;
    thumbnails:ThumbnailsResponse;
}

export type ErrCallback = (err?:Error)=>void;
export type StorePhotoCallback = (err:Error, response?:StorePhotoResponse) => void;
export type MediaListCallback = (err, media?:MediaNode[])=>void;
export type MediaNodeCallback = (err, media?:MediaNode)=>void;

/**
 * KB Media APIs
 * @namespace jibo.kb.media
 */

/** MediaModel Class. The Media Model subclass
 *
 * @example
 * jibo.kb.media#loadMedia( (err, media) => console.log(media) );
 * @class MediaModel
 * @extends jibo.kb.Model
 * @memberof jibo.kb.media
 */
export default class MediaModel extends Model {

    public MediaNode = MediaNode;
    public MediaType = MediaType;
    public ThumbnailType = ThumbnailType;
    /**
     * Strongly-typed events emitted by this model
     * @intdocs
     * @name jibo.kb.media.MediaModel#events
     * @type {jibo.kb.media~MediaModelEvents}
     */
    public events = new MediaModelEvents();

    // WebSocket client for listening for events from KBService
    private _wsClient: WSClient;

    constructor(kbNames:string|string[], httpUrl:string=null) {
        super(kbNames, httpUrl);
        this._listenForWSMessages();
    }

    /** Load media nodes in the media list.  Deleted media nodes are
     * excluded. If callback is omitted a promise is returned instead.
     *
     * @method jibo.kb.media.MediaModel#loadMedia
     * @param {Function} [callback] Called with (err, media). If callback
     * is omitted a promise that resolves to `media` is returned
     * instead.
     * @returns {Promise} A promise that resolves with the list of
     * media nodes if the callback is omitted.
     */
    public loadMedia(callback:MediaListCallback);
    public loadMedia():Promise<MediaNode[]>;
    @promisify
    public loadMedia(callback?:MediaListCallback):void|Promise<MediaNode[]> {
        this.loadMediaAll( (err, media) => {
            if (!err) {
                callback(null, this._onlyNotDeleted(media));
            } else {
                callback(err);
            }
        });
    }

    /** Load all media nodes, including deleted ones.
     *
     * @method jibo.kb.media.MediaModel#loadMediaAll
     * @param {Function} [callback] Called with (err, media). If callback
     * is omitted a promise that resolves to `media` is returned
     * instead.
     * @returns {Promise} A promise that resolves with the list of
     * media nodes if the callback is omitted.
     */
    public loadMediaAll(callback:MediaListCallback);
    public loadMediaAll():Promise<MediaNode[]>;
    @promisify
    public loadMediaAll(callback?:MediaListCallback):void|Promise<MediaNode[]> {
        this.loadRoot(null, (err, rootNode) => {
            log.iferr(err, 'loadRoot');
            if (!err && rootNode) {
                let mediaIds = rootNode.getEdges('media');
                this.load(mediaIds, (err, nodes) => {
                    log.iferr(err, 'load');
                    callback(err, <MediaNode[]>nodes);
                });
            } else {
                callback(err);
            }
        });
    }


    /** Load the node for the thumbnail for a given media item node.
     * @method jibo.kb.media.MediaModel#loadThumbnail
     * @param {jibo.kb.media.MediaNode} mediaNode The media node you want the thumbnail to.
     * @param {jibo.media#ThumbnailType} [type=thumb_robot] Type of thumbnail.
     * @param {function} callback Called with the media node for the
     * thumbnail, or `undefined` if there is no thumbnail of that
     * type.
     */
    public loadThumbnail(mediaNode:MediaNode, callback:MediaNodeCallback);
    public loadThumbnail(mediaNode:MediaNode, type:ThumbnailType, callback:MediaNodeCallback);
    public loadThumbnail(mediaNode:MediaNode, type:ThumbnailType):Promise<MediaNode>;
    @promisify
    public loadThumbnail(mediaNode:MediaNode, two, three?):void|Promise<MediaNode> {
        let type;
        let callback;
        if (typeof two === 'function') {
            type = null;
            callback = two;
        } else {
            type = two;
            callback = three;
        }

        type = type || ThumbnailType.thumb_robot;

        let thumbId = mediaNode.getThumbnailId(type);
        this.load(thumbId, callback);
    }


    /** Get the url for the thumbnail for a given media item node.
     * @method jibo.kb.media.MediaModel#getThumbnailUrl
     * @param {jibo.kb.media.MediaNode} mediaNode The media node you want the thumbnail to.
     * @param {jibo.media#ThumbnailType} [type=thumb_robot] Type of thumbnail.
     * @returns {string} Url for the thumbnail of that type, if any,
     * `undefined` otherwise.
     */
    public getThumbnailUrl(mediaNode:MediaNode, type?:ThumbnailType):string {
        type = type || ThumbnailType.thumb_robot;
        let thumbId = mediaNode.getThumbnailId(type);
        return Runtime.instance.media.getUrl(thumbId);
    }


    /** Download a list of thumbnails to the local image store.
     *
     * @method jibo.kb.media.MediaModel#downloadThumbnails
     * @param {string[]} ids Array of thumnails Content IDs to download.
     * @param {Function} [callback] Called with err object if there
     * was an error. If callback is omitted a promise is returned instead.
     * @returns {Promise} A promise that resolves when the operation is
     * finished.
     * @private
     */
    // not ready for prime time yet
    public downloadThumbnails(ids:string[], callback:ErrCallback);
    public downloadThumbnails(ids:string[]):Promise<void>;
    @promisify
    public downloadThumbnails(ids:string[], callback?:ErrCallback):void|Promise<void> {
        let url = `${this.httpUrl}/v1/media/downloadThumbnails`;
        let params = {
            ids: ids,
            type: 'image'
        };
        request.post(url, {json: params}, (err, res, body) => {
            err = this._checkStatusCode(err, res, body);
            log.iferr(err, 'request.post', url);
            if (callback) {
                callback(err);
            }
        });
    }


    /** Download a photo to the local image store.
     *
     * @method jibo.kb.media.MediaModel#downloadPhoto
     * @param {string} id Content ID of photo to download.
     * @param {Function} [callback] Called with err object if there
     * was an error. If callback is omitted a promise is returned instead.
     * @returns {Promise} A promise that resolves when the operation is
     * finished.
     * @private
     */
    // not ready for prime time yet
    public downloadPhoto(id:string, callback:ErrCallback);
    public downloadPhoto(id:string):Promise<void>;
    @promisify
    public downloadPhoto(id:string, callback?:ErrCallback):void|Promise<void> {
        let url = `${this.httpUrl}/v1/media/downloadPhoto`;
        let params = {
            id: id,
            type: 'image'
        };
        request.post(url, {json: params}, (err, res, body) => {
            err = this._checkStatusCode(err, res, body);
            log.iferr(err, 'request.post', url);
            if (callback) {
                callback(err);
            }
        });
    }


    /** Internal call to the MediaListManager to store the photo and
     * its thumbnails and update the KB to reflect the cloud changes.
     *
     * @intdocs
     * @method jibo.kb.media.MediaModel#storePhoto
     * @param {Function} [callback] Called with err object if there
     * was an error. If callback is omitted a promise is returned instead.
     * @returns {Promise} A promise that resolves when the operation is
     * finished.
     */
    public storePhoto(data:any, callback:StorePhotoCallback):void;
    public storePhoto(data:any):Promise<StorePhotoResponse>;
    @promisify
    public storePhoto(data:any, callback?:StorePhotoCallback):void|Promise<StorePhotoResponse> {
        let url = `${this.httpUrl}/v1/media/storePhoto`;
        let params = data;
        request.post(url, {body: params, json: true}, (err, res, body) => {
            err = this._checkStatusCode(err, res, body);
            log.iferr(err, 'request.post', url);
            if (callback) {
                callback(err, body);
            }
        });
    }


    /** Internal call to update the KB to reflect the cloud changes
     * from deleting a photo.  Currently just causes a full sync of
     * the media list.
     *
     * @intdocs
     * @method jibo.kb.media.MediaModel#deletePhoto
     * @param {Function} [callback] Called with err object if there
     * was an error. If callback is omitted a promise is returned instead.
     * @returns {Promise} A promise that resolves when the operation is
     * finished.
     */
    public deletePhoto(id:string, callback:ErrCallback):void;
    public deletePhoto(id:string):Promise<void>;
    @promisify
    public deletePhoto(id:string, callback?:ErrCallback):void|Promise<void> {
        let url = `${this.httpUrl}/v1/media/deletePhoto`;
        let params = {
            id: id
        };
        request.post(url, {json: params}, (err, res, body) => {
            err = this._checkStatusCode(err, res, body);
            log.iferr(err, 'request.post', url);
            if (callback) {
                callback(err);
            }
        });
    }


    // Listen for WebSocket messages from the KBService
    private _listenForWSMessages(): void {
        this._wsClient = new WSClient(this.httpUrl);
        this._wsClient.on('message', this._wsMessageReceived.bind(this));
    }

    // Message receipt handler for WebSocket messages from KBService
    private _wsMessageReceived(message) {
        switch(message) {
            case 'MediaListChanged':
                console.log('MediaModel: received MediaListChanged event; emitting MediaModelEvents.mediaListChanged');
                this.events.mediaListChanged.emit();
                break;
            default:
                console.warn('MediaModel: received unknown message from KBService', message);
        }
    }

    /** Filter out media items that have been deleted.
     *
     * @method jibo.kb.media.MediaModel#_onlyNotDeleted
     * @param {jibo.kb.media.MediaNode[]} media Media nodes to filter.
     * @returns {jibo.kb.media.MediaNode[]} Media nodes where `isDeleted` is
     * `false`.
     * @private
     */
    private _onlyNotDeleted(media:MediaNode[]):MediaNode[] {
        return media.filter( (media) => { return !media.data.isDeleted; } );
    }


    /** Check http request result for null error object and 2xx result code and
     * generate an error object if not (or pass through non null error object).
     *
     * @method jibo.kb.WebClient#_checkStatusCode
     * @param {Error} err Error object returned from request.
     * @param {Object} res Http request result object.
     * @param {string} [message] Message to add to error object.
     * @returns {Error} Error object or null.
     * @private
     */
    private _checkStatusCode(err:Error, res, message:string=null):Error {
        if (!err) {  // game over if we already have an err
            if (res.statusCode < 200 || res.statusCode > 299) {
                let description = 'HTTP Error Code '+res.statusCode;
                if (message) {
                    description += message;
                }
                err = new Error(description);
            }
        }
        return err;
    }
}
