import FaceRenderer from '../FaceRenderer';

/**
 * Utilities for DisplayObjects.
 * @class DisplayUtils
 * @memberof jibo.face
 * @intdocs
 */
class DisplayUtils {

    static readonly LEFT:string = 'LEFT';
    static readonly RIGHT:string = 'RIGHT';
    static readonly CENTER:string = 'CENTER';
    static readonly TOP:string = 'TOP';
    static readonly BOTTOM:string = 'BOTTOM';

    /**
     * Get the uniform scale required for DisplayObject to fit given dimensions.
     * @method jibo.face.DisplayUtils#getScaleByWidthHeight
     * @param {PIXI.DisplayObject} displayObject - DisplayObject to get the scale for.
     * @param {number} width - Target width.
     * @param {number} height - Target height.
     * @returns {number} Uniform scale to apply to given DisplayObject for it to fit given dimension.
     */
    public static getScaleByWidthHeight(displayObject: PIXI.DisplayObject, width: number, height: number): number {
        const rect: PIXI.Rectangle = displayObject.getBounds();
        return Math.max(width / rect.width * displayObject.scale.x, height / rect.height * displayObject.scale.y);
    }

    /**
     * Check whether display if contained by another display.
     * @method jibo.face.DisplayUtils#isContained
     * @param {PIXI.DisplayObject} display - DisplayObject checking for containment.
     * @param {PIXI.Container} container - Container to check if display is contained within.
     * @returns {boolean} `true` if display is contained within container.
     */
    public static isContained(display: PIXI.DisplayObject, container: PIXI.Container): boolean {
        let parent: PIXI.Container = display.parent;
        while (parent) {
            if (parent === container) {
                return true;
            }
            parent = parent.parent;
        }
        return false;
    }

    /**
     * Takes position value provided for the element and makes sure that it is positioned properly + processes LEFT/RIGHT/CENTER/TOP/BOTTOM alignment options
     * Remember, that RIGHT/BOTTOM alignment does not include actual element bounds, this should be handled separately
     * @method jibo.face.DisplayUtils#getElementPosition
     * @param {Object} position - Position data for the element
     * @returns {PIXI.Point} Contains proper point value of the element on the screen
     */
    public static getElementPosition(position: any): PIXI.Point {
        let point = new PIXI.Point(0, 0); //this means LEFT.TOP position basically
        let margin = {x: 0, y: 0};
        if (position.margin) {
            isNaN(position.margin) ? Object.assign(margin, position.margin) : Object.assign(margin, { x: Number(position.margin), y: Number(position.margin)});
        }

        //getting our x value
        if (!isNaN(position.x)) {
            point.x = Number(position.x) + margin.x;
        } else if (DisplayUtils.CENTER === position.x) {
            //center horizontal position
            point.x = FaceRenderer.WIDTH / 2;
        } else if (DisplayUtils.LEFT === position.x) {
            //left side position with margin applied
            point.x = margin.x;
        } else if (DisplayUtils.RIGHT === position.x) {
            //right side position with margin applied
            point.x = FaceRenderer.WIDTH - margin.x;
        }

        //getting our y value
        if (!isNaN(position.y)) {
            point.y = Number(position.y) + margin.y;
        } else if (DisplayUtils.CENTER === position.y) {
            //center vertical position
            point.y = FaceRenderer.HEIGHT / 2;
        } else if (DisplayUtils.TOP === position.y) {
            //top side position with margin applied
            point.y = margin.y;
        } else if (DisplayUtils.BOTTOM === position.y) {
            //bottom side position with margin applied
            point.y = FaceRenderer.HEIGHT - margin.y;
        }

        return point;
    }

}
export default DisplayUtils;
