import {Node} from 'jibo-kb';
import {MediaType} from './MediaManagerService';
import {ThumbnailType} from './Media';
export {ThumbnailType} from './Media';


/** Specific type of node for media. All nodes returned by {@link jibo.kb.media.MediaModel}
 * will be MediaNodes.
 *
 * @class MediaNode
 * @extends jibo.kb.Node
 * @memberof jibo.kb.media
 */
export default class MediaNode extends Node {
    public data: {
        path:string,
        type:MediaType,
        reference:string,
        accountId:string,
        loopId:string,
        url:string,
        isEncrypted:boolean,
        isDeleted:boolean,
        created:number
    };


    /** UUID of the media.
     *
     * @name jibo.kb.media.MediaNode#id
     * @type {String}
     */
    public get id():string {
        return this._id;
    }


    /** The loopId this media belongs to.
     *
     * @name jibo.kb.media.MediaNode#loopId
     * @type {String}
     */
    public get loopId():string {
        return this.data.loopId;
    }


    /** The url that points to the actual media content.
     *
     * @name jibo.kb.media.MediaNode#url
     * @type {String}
     */
    public get url():string {
        return this.data.url;
    }


    /** Get the content ID of the thumbnail for this media item.
     * @method jibo.kb.media.MediaNode#getThumbnailId
     * @param {jibo.media#ThumbnailType} [type=thumb_robot] Type of thumbnail.
     * @returns {string} Content ID of the thumbnail, if any,
     * `undefined` otherwise.
     */
    public getThumbnailId(type?:ThumbnailType):string {
        type = type || ThumbnailType.thumb_robot;
        return this.getEdges(ThumbnailType[type])[0];
    }
}
