import {EventEmitter} from 'events';
import {HTTPClient} from 'jibo-client-framework';
import {isInitialized} from '../../utils/decorators';


/** Enum of media types.
 * @typedef jibo.media.MediaManager#MediaType
 * @property image {string} 'image'
 * @property recording {string} 'recording'
 * @property thumb {string} 'thumb'
 * @property thumb_robot {string} 'thumb_robot'
 * @property audio {string} 'audio'
 */
export enum MediaType {
    image       = <any>'image',
    recording   = <any>'recording',
    thumb       = <any>'thumb',
    thumb_robot = <any>'thumb_robot',
    audio       = <any>'audio'
}

/** Interface (internal only)
 * @typedef jibo.media.MediaManager#UploadRequest
 * @property contentID {string}
 * @property immediate {boolean}
 * @property keepLocal {boolean}
 * @property type {jibo.media.MediaManager#MediaType}
 * @property reference {string}
 * @intdocs
 */
interface UploadRequest {
    contentID:string;
    immediate:boolean;
    keepLocal:boolean;
    type:MediaType;
    reference:string;
}

/** Interface (internal only)
 * @typedef jibo.media.MediaManager#DownloadRequest
 * @property contentID {string}
 * @property immediate {boolean}
 * @property type {jibo.media.MediaManager#MediaType}
 * @intdocs
 */
interface DownloadRequest {
    contentID:string;
    immediate:boolean;
    type:MediaType;
}

/** Interface (internal only)
 * @typedef jibo.media.MediaManager#DeleteRequest
 * @property contentID {string}
 * @property immediate {boolean}
 * @property deleteLocal {boolean}
 * @property deleteRemote {boolean}
 * @property type {jibo.media.MediaManager#MediaType}
 * @intdocs
 */
interface DeleteRequest {
    contentID:string;
    immediate:boolean;
    deleteLocal:boolean;
    deleteRemote:boolean;
    type:MediaType;
}

type ErrCallback = (err:Error) => void;


/** Media Manager Service
 *
 * @class MediaManager
 * @memberof jibo.media
 * @extends {EventEmitter}
 * @intdocs
 */
export class MediaManagerService extends EventEmitter {
    public MediaType: typeof MediaType;
    private mediaManagerServiceUrl:string;
    private httpClient:HTTPClient;
    private isInitialized:boolean = false;


    constructor() {
        super();
        this.MediaType = MediaType;
        this.isInitialized = false;
    }


    init(service, callback) {
        if (!service.host || typeof service.host !== 'string') {
            throw new Error(`Missing required service.host`);
        }
        this.mediaManagerServiceUrl = "http://" + service.host + ":" + service.port;
        this.isInitialized = true;

        this.httpClient = new HTTPClient(service.host, service.port);
        process.nextTick(callback);
    }


    /** Send media from the local library to the cloud.
     *
     * @method jibo.media.MediaManager#upload
     * @param {string} contentID Content ID of the local media to upload.
     * @param {boolean} immediate Wait until the upload is finished before calling callback.
     * @param {boolean} keepLocal If `false` local copy of media will be removed after upload.
     * @param {jibo.media.MediaManager} mediaType Enumerated value of the media type.
     * @param {string} reference Optional content ID reference (for
     * thumbnails to point to the main content)
     * @param {function} callback Called when done.
     * @intdocs
     */
    @isInitialized
    upload(contentID:string, immediate:boolean, keepLocal:boolean, mediaType:MediaType, reference:string, callback:ErrCallback) {
        let data:UploadRequest = {
            contentID: contentID,
            immediate: immediate,
            keepLocal: keepLocal,
            type: mediaType,
            reference: reference
        };

        this.httpClient.postJSON('/media-manager/upload', data, (err:Error, response) => {
            callback(err);
        });
    }


    /** Download media from the cloud to the local library.
     * If the media is already in the local library the call
     * will succeed the same as if it downloaded it (but faster).
     *
     * @method jibo.media.MediaManager#download
     * @param {string} contentID Content ID of the local media to upload.
     * @param {boolean} immediate If `true` wait until the upload is finished before calling callback.
     * @param {boolean} keepLocal If `false` local copy of media will be removed after upload.
     * @param {jibo.media.MediaManager} mediaType Enumerated value of the media type.
     * @param {string} reference Optional content ID reference (for
     * thumbnails to point to the main content)
     * @param {function} callback Called when done.
     * @intdocs
     */
    @isInitialized
    download(contentID:string, immediate:boolean, mediaType:MediaType, callback:ErrCallback) {
        let data:DownloadRequest = {
            contentID: contentID,
            immediate: immediate,
            type: mediaType
        };

        this.httpClient.postJSON('/media-manager/download', data, (err:Error, response) => {
            callback(err);
        });
    }


    /** Delete media from the cloud and/or local library.
     *
     * @method jibo.media.MediaManager#delete
     * @param {string} contentID Content ID of the media to delete.
     * @param {boolean} immediate If `true` wait until the delete is
     * finished finished in the cloud before calling callback.
     * @param {boolean} deleteLocal Delete the local library copy.
     * @param {boolean} deleteRemote Delete the cloud copy.
     * @param {jibo.media.MediaManager} mediaType Enumerated value of the media type.
     * @param {function} callback Called when done.
     * @intdocs
     */
    @isInitialized
    delete(contentID:string, immediate:boolean, deleteLocal:boolean, deleteRemote:boolean, mediaType:MediaType, callback:ErrCallback) {
        let data:DeleteRequest = {
            contentID: contentID,
            immediate: immediate,
            deleteLocal: deleteLocal,
            deleteRemote: deleteRemote,
            type: mediaType
        };

        this.httpClient.postJSON('/media-manager/delete', data, (err:Error, response) => {
            callback(err);
        });
    }
}

export default MediaManagerService;
