import MimPrompt from './MimPrompt';
import MimState, {States} from './MimState';
import {selectItem} from './WeightedRotation';
import fs = require('fs');
import vm = require('vm');
import path = require('path');
import {constant} from '../../utils/decorators';
import {Node} from 'jibo-kb';

type PromptCategory = 'Entry-Core' | 'Errors' | 'Response';
const PROMPT_CATEGORY_ENTRY:'Entry-Core' = 'Entry-Core';
const PROMPT_CATEGORY_ERROR:'Errors' = 'Errors';
const PROMPT_CATEGORY_RESPONSE:'Response' = 'Response';

type PromptSubCategory = 'Q' | 'AN' | 'NM' | 'NI' | 'HoldReturn' | 'Verbose' | 'Truncated' | 'Thanks';
const PROMPT_SUB_CATEGORY_QUESTION:'Q' = 'Q';
const PROMPT_SUB_CATEGORY_ANNOUNCEMENT:'AN' = 'AN';
const PROMPT_SUB_CATEGORY_NO_MATCH:'NM' = 'NM';
const PROMPT_SUB_CATEGORY_NO_INPUT:'NI' = 'NI';
const PROMPT_SUB_CATEGORY_HOLD_RETURN:'HoldReturn' = 'HoldReturn';
const PROMPT_SUB_CATEGORY_VERBOSE:'Verbose' = 'Verbose';
const PROMPT_SUB_CATEGORY_TRUNCATED:'Truncated' = 'Truncated';
const PROMPT_SUB_CATEGORY_THANKS:'Thanks' = 'Thanks';
type ErrorSubCategory = typeof PROMPT_SUB_CATEGORY_NO_MATCH | typeof PROMPT_SUB_CATEGORY_NO_INPUT;

type ThanksOption = 'ignore' | 'respondAndListen' | 'respondAndEnd';
export class ThanksOptions {
    @constant
    public static IGNORE:'ignore' = 'ignore';
    @constant
    public static RESPOND_AND_LISTEN:'respondAndListen' = 'respondAndListen';
    @constant
    public static RESPOND_AND_END:'respondAndEnd' = 'respondAndEnd';
}

const TYPE_AN = 'announcement';
const TYPE_OR = 'optional-response';
const TYPE_Q = 'question';
export class MimTypes {
    @constant
    public static ANNOUNCEMENT = TYPE_AN;
    @constant
    public static OPTIONAL_RESPONSE = TYPE_OR;
    @constant
    public static QUESTION = TYPE_Q;
};

export class ListenModes {
    @constant
    public static NORMAL = 'NORMAL';
    @constant
    public static OR = 'OR';
    @constant
    public static UI = 'UI';
    @constant
    public static NO_BODY = 'NO_BODY';
};

/**
 * MIM configuration data generated from the .mim files.
 * @class MimConfig
 * @memberof jibo.mim
 * @private
 */
export default class MimConfig {
    public mimId:string;
    public mimType:string;
    public ruleName:string;
    public gui:any;
    public timeout:number;
    public noMatchesForGUI:number;
    public noInputsForGUI:number;
    public bargeIn:boolean;
    public esAutoTagging:any;
    public ignoreNoMatch:boolean;
    public prompts:MimPrompt[];
    public listenMode:string;
    public thanksHandling:ThanksOption;
    public parseAllASR:boolean;
    private vmContext:vm.Context;

    /**
     * Promised loading of a single .mim file.
     * @method jibo.mim.MimConfig~load
     * @param {string} filePath Path to the .mim file.
     * @returns {Promise<MimConfig>} Promise to load a new MimConfig instance.
     * @static
     */
    public static load(filePath:string):Promise<MimConfig> {
        return new Promise((resolve, reject) => {
            fs.readFile(filePath, 'utf8', (error, result) => {
                if (error) {
                    reject(error);
                } else {
                    let mim = new MimConfig();
                    mim.mimId = path.basename(filePath, path.extname(filePath));
                    mim.initWithJSON(JSON.parse(result));
                    resolve(mim);
                }
            });
        });
    }

    constructor() {
        this.mimId = '';
        this.mimType = '';
        this.ruleName = '';
        this.gui = null;
        this.timeout = 0;
        // the default behavior here is to display the GUI immediately upon asking a Question
        this.noMatchesForGUI = 0;
        this.noInputsForGUI = 0;
        this.bargeIn = true;
        this.esAutoTagging = true;
        this.ignoreNoMatch = false;
        this.listenMode = ListenModes.NORMAL;
        this.thanksHandling = ThanksOptions.IGNORE;
        this.parseAllASR = false;

        this.prompts = [];
    }
    
    /**
     * If the Mim has a gui available, either as sampleUtterances or guiConfig.
     * @name jibo.mim.MimConfig~hasGui
     * @type {Boolean}
     * @readOnly
     */
    public get hasGui() {
        return (!!this.gui && !!this.gui.data);
    }

    /**
     * Pick a prompt and get the text for it.
     * @method jibo.mim.MimConfig~getPromptText
     * @param {jibo.mim.MimState} mimState State of the active MIM.
     * @param {any} promptData Dictionary of variables to use for condition evaluation and text replacement.
     * @param {jibo.kb.Node} [rotationNode] Node used to store data
     * @return {Object} An object with 'text', 'id', and 'autoRuleOverride' properties.
     */
    public getPromptText(mimState:MimState, promptData:any, rotationNode?:Node):{id:string, text:string, autoRuleOverride:any} {
        let entryPromptSubCategory:PromptSubCategory;
        switch (this.mimType) {
            case TYPE_Q:
                entryPromptSubCategory = PROMPT_SUB_CATEGORY_QUESTION;
                break;
            case TYPE_AN:
                entryPromptSubCategory = PROMPT_SUB_CATEGORY_ANNOUNCEMENT;
                break;
            case TYPE_OR:
                entryPromptSubCategory = PROMPT_SUB_CATEGORY_ANNOUNCEMENT;
                break;
            default:
                console.error(`In MiM ${this.mimId}, incorrect mimType of ${this.mimType}`);
                break;
        }
        //internal usage of not supplying any information to just get a quick entry prompt
        if (!mimState) {
            const prompt = this.getPromptWithCategoryAndSubCategory(PROMPT_CATEGORY_ENTRY,
                                                            entryPromptSubCategory,
                                                            null, rotationNode);
            return {id:prompt.id, text:prompt.getPromptText().trim(), autoRuleOverride: prompt.autoRuleOverride};
        }
        //make a sandbox for prompt condition evaluation and prompt value replacement
        let promptDataSandbox:vm.Context;
        if (promptData) {
            promptDataSandbox = this.getSandbox(promptData);
        }
        let prompt:MimPrompt = null;
        switch (mimState.lastResultState) {
            case States.ENTRY:
                prompt = this.getPromptWithCategoryAndSubCategory(PROMPT_CATEGORY_ENTRY,
                                                                entryPromptSubCategory,
                                                                promptDataSandbox, rotationNode);
                break;
            case States.VERBOSE:
                prompt = this.getPromptWithCategoryAndSubCategory(PROMPT_CATEGORY_ENTRY,
                                                                PROMPT_SUB_CATEGORY_VERBOSE,
                                                                promptDataSandbox, rotationNode);
                if (!prompt) {
                    prompt = this.getPromptWithCategoryAndSubCategory(PROMPT_CATEGORY_ENTRY,
                                                                entryPromptSubCategory,
                                                                promptDataSandbox, rotationNode);
                }
                break;
            case States.TRUNCATED:
                prompt = this.getPromptWithCategoryAndSubCategory(PROMPT_CATEGORY_ENTRY,
                                                                PROMPT_SUB_CATEGORY_TRUNCATED,
                                                                promptDataSandbox, rotationNode);
                if (!prompt) {
                    prompt = this.getPromptWithCategoryAndSubCategory(PROMPT_CATEGORY_ENTRY,
                                                                entryPromptSubCategory,
                                                                promptDataSandbox, rotationNode);
                }
                break;
            case States.HOLD_RETURN:
                prompt = this.getPromptWithCategoryAndSubCategory(PROMPT_CATEGORY_ENTRY,
                                                                PROMPT_SUB_CATEGORY_HOLD_RETURN,
                                                                promptDataSandbox, rotationNode);
                if (!prompt) {
                    prompt = this.getPromptWithCategoryAndSubCategory(PROMPT_CATEGORY_ENTRY,
                                                                    entryPromptSubCategory,
                                                                    promptDataSandbox,
                                                                    rotationNode);
                }
                break;
            case States.THANKS:
                prompt = this.getPromptWithCategoryAndSubCategory(PROMPT_CATEGORY_RESPONSE,
                                                                PROMPT_SUB_CATEGORY_THANKS,
                                                                promptDataSandbox, rotationNode);
                break;
            case States.NO_MATCH:
                prompt = this.getErrorPrompt(PROMPT_SUB_CATEGORY_NO_MATCH, promptDataSandbox,
                                            mimState.noMatchCount, rotationNode);
                break;
            case States.NO_INPUT:
                prompt = this.getErrorPrompt(PROMPT_SUB_CATEGORY_NO_INPUT, promptDataSandbox,
                                            mimState.noInputCount, rotationNode);
                break;
            default:
                console.error(`Invalid lastResultState: ${mimState.lastResultState}`);
                break;
        }
        //if there is a node to track prompt rotation, then save it because we just updated it.
        if (rotationNode) {
            //don't wait on the result, because we don't really care
            rotationNode.save();
        }
        if (!prompt) {
            console.error(`Unable to find a valid prompt for mim ${this.mimId} - last result state: ${mimState.lastResultState}`);
            return {id:null, text:'', autoRuleOverride: null};
        }
        //if we aren't doing a TTS, then don't say anything
        if (prompt.media !== 'TTS') {
            return {id:prompt.id, text:'', autoRuleOverride: prompt.autoRuleOverride};
        }

        //On Tuesday, it will be: ${conditions} ${inLocale} With a high in the: ${highTemp} And a low in the: ${lowTemp}
        let promptText = '';
        if (promptDataSandbox) {
            let script_text = '`' + prompt.getPromptText() + '`';
            try {
                promptText = vm.runInContext(script_text, promptDataSandbox);
            } catch (e) {
                console.error(`Error parsing prompt text: ${prompt.getPromptText()} - error: ${e.message}`);
            }
        } else {
            promptText = prompt.getPromptText();
        }
        return {id:prompt.id, text:promptText, autoRuleOverride: prompt.autoRuleOverride};
    }
    
    /**
     * Generate a view config object for the MIM GUI, using the javascript code from the .mim file.
     * @method jibo.mim.MimConfig~getJavascriptGUI
     * @param {any} promptData Prompt data for the MIM
     * @return {any} The generated view config object
     */
    public getJavascriptGUI(promptData:any):any {
        if (!this.gui || !this.gui.data || this.gui.type !== 'Javascript') {
            return null;
        }
        const sandbox = this.getSandbox(promptData);
        let viewConfig = null;
        let code:string = this.gui.data;
        
        try {
            if (code.match(/^\s*{/)) {
                //if the code is set up as a Javascript Object literal, then handle it as such
                code = '(function() {\nreturn ' + code + '})()';
                viewConfig = vm.runInContext(code, sandbox);
            } else {
                //otherwise, treat as function contents and wrap it in an auto-executing function
                code = '(function() {\n' + code + '})()';
                viewConfig = vm.runInContext(code, sandbox);
            }
        } catch (e) {
            console.error(`Error when trying to get GUI for MIM ${this.mimId}: `, e);
        }
        return viewConfig;
    }
    
    /**
     * See if MimConfig has error prompts of the corresponding type and index.
     * @method jibo.mim.MimConfig~hasErrorPrompt
     * @param {String} error The error type
     * @param {Number} index The prompt index
     * @return {Boolean}
     */
    public hasErrorPrompt(error:string, index:number):boolean {
        let errorCategory:string;
        if (error === 'noInput') {
            errorCategory = PROMPT_SUB_CATEGORY_NO_INPUT;
        } else if (error === 'noMatch') {
            errorCategory = PROMPT_SUB_CATEGORY_NO_MATCH;
        } else {
            return false;
        }
        for (let prompt of this.prompts) {
            if (prompt.promptCategory === PROMPT_CATEGORY_ERROR &&
                prompt.promptSubCategory === errorCategory && prompt.index === index) {
                return true;
            }
        }
        return false;
    }
    
    /**
     * See if MimConfig has at least one verbose prompt.
     * @method jibo.mim.MimConfig~hasVerbosePrompt
     * @return {Boolean}
     */
    public hasVerbosePrompt():boolean {
        for (let prompt of this.prompts) {
            if (prompt.promptCategory === PROMPT_CATEGORY_ENTRY &&
                prompt.promptSubCategory === PROMPT_SUB_CATEGORY_VERBOSE) {
                return true;
            }
        }
        return false;
    }
    
    /**
     * See if MimConfig has at least one truncated prompt.
     * @method jibo.mim.MimConfig~hasTruncatedPrompt
     * @return {Boolean}
     */
    public hasTruncatedPrompt():boolean {
        for (let prompt of this.prompts) {
            if (prompt.promptCategory === PROMPT_CATEGORY_ENTRY &&
                prompt.promptSubCategory === PROMPT_SUB_CATEGORY_TRUNCATED) {
                return true;
            }
        }
        return false;
    }
    
    /**
     * See if MimConfig has at least one thanks prompt.
     * @method jibo.mim.MimConfig~hasThanksPrompt
     * @return {Boolean}
     */
    public hasThanksPrompt():boolean {
        for (let prompt of this.prompts) {
            if (prompt.promptCategory === PROMPT_CATEGORY_RESPONSE &&
                prompt.promptSubCategory === PROMPT_SUB_CATEGORY_THANKS) {
                return true;
            }
        }
        return false;
    }

    public initWithJSON(data):void {
        this.mimType = data.mim_type;
        //'announce' was changed to 'announcement' in our database of MIM files, but we potentially
        //have a bunch of mims that have not been updated
        if (this.mimType === 'announce') {
            this.mimType = TYPE_AN;
        }
        this.ruleName = data.rule_name;
        if (data.gui) {
            this.gui = data.gui;
        } else if (data.sample_utterances) {
            // Handle deprecation of sample_utterances
            const gui = {
                title: '',
                buttons: []
            };
            const utterances:string[] = data.sample_utterances.split(',');
            for (let i = 0; i < utterances.length; ++i) {
                const utter = utterances[i].trim();
                const button = {
                    label: utter,
                    color: 'default',
                    icon: '',
                    utterance: utter,
                    notes: ''
                };
                if (utter.toLowerCase() === 'yes') {
                    button.color = 'confirm';
                    button.icon = 'jibo://resources/actionIcons/ok.png';
                } else if (utter.toLowerCase() === 'no') {
                    button.color = 'cancel';
                    button.icon = 'jibo://resources/actionIcons/cancel.png';
                }
                gui.buttons.push(button);
            }
            this.gui = {
                type: 'Menu',
                data: gui,
                pause: true
            };
        }
        //convert string to number
        this.timeout = parseFloat(data.timeout);
        // timeout must be greater than 0 (although values < 1 are probably not useful)
        if (this.mimType !== TYPE_AN && !(this.timeout > 0)) {
            console.error(`Timeout is an invalid value (${this.timeout}) in mim ${this.mimId}`);
            //default to avoid immediately breaking things
            this.timeout = 6;
        }
        //handle older files with num_tries_for_gui
        if (data.num_tries_for_gui) {
            this.noInputsForGUI = this.noMatchesForGUI = parseInt(data.num_tries_for_gui);
        } else {
            //handle newer files with split values
            this.noInputsForGUI = parseInt(data.no_inputs_for_gui);
            this.noMatchesForGUI = parseInt(data.no_matches_for_gui);
        }
        //ensure that noMatchesForGUI and noInputsForGUI has an integer value of at least 0
        if (!(this.noMatchesForGUI >= 0)) {
            this.noMatchesForGUI = 0;
        }
        if (!(this.noInputsForGUI >= 0)) {
            this.noInputsForGUI = 0;
        }
        //bargeIn and esAutoTagging both default to true
        this.bargeIn = data.barge_in !== false;
        this.esAutoTagging = data.es_auto_tagging === undefined ? true : data.es_auto_tagging;
        //Optional Response mims always ignore no match errors
        if (this.mimType === TYPE_OR) {
            this.ignoreNoMatch = true;
            this.listenMode = ListenModes.OR;
        }
        //NOTE: might not use this feature, but adding it here just in case
        if (data.listenMode) {
            switch(data.listenMode) {
                case 'OR':
                    this.listenMode = ListenModes.OR;
                    break;
                case 'UI':
                    this.listenMode = ListenModes.UI;
                    break;
                case 'NO_BODY':
                    this.listenMode = ListenModes.NO_BODY;
                    break;
            }
        }
        //only Optional Response mims are allowed to handle thanks mim-globals
        if (this.mimType === TYPE_OR) {
            this.thanksHandling = data.thanks_handling || ThanksOptions.IGNORE;
        }
        //defaults to false
        this.parseAllASR = data.parse_all_asr === true;

        if (data.prompts) {
            for(let prompt_data of data.prompts) {
                this.addPromptWithJSON(prompt_data);
            }
        }
    }

    private getPromptWithCategoryAndSubCategory(category:PromptCategory,
                                                sub_category:PromptSubCategory,
                                                promptData:any,
                                                rotationNode:Node):MimPrompt {
        let prompts:MimPrompt[] = [];
        let result:MimPrompt = null;
        // prompts already used, tracked in case we need to do a reset
        let usedPromptIds:any = null;
        //get the used ids from the KB node, setting up empty containers if we need to initialize it
        if (rotationNode) {
            let mimData = rotationNode.data[this.mimId];
            if (!mimData) {
                mimData = rotationNode.data[this.mimId] = {};
            }
            usedPromptIds = mimData[sub_category];
            //if it is an array, then it was data from the initial implementation and should be
            //wiped. Later, we can remove the || part of this check, and leave it as just a null
            //check
            if (!usedPromptIds || Array.isArray(usedPromptIds)) {
                usedPromptIds = mimData[sub_category] = {};
            }
        }

        //go through the prompts, getting valid ones, and setting aside used ones
        for (let prompt of this.prompts) {
            if (prompt.promptCategory === category && prompt.promptSubCategory === sub_category) {
                prompts.push(prompt);
            }
        }
        //get a prompt if we can
        result = selectItem(prompts, (prompt) => {
            return this.promptMeetsCondition(prompt, promptData);
        }, usedPromptIds);
        return result;
    }
    
    private getErrorPrompt(promptSubCategory:ErrorSubCategory, promptData:any, index:number, rotationNode:Node) {
        let prompts:MimPrompt[] = [];
        let result:MimPrompt = null;
        let usedPromptIds:any = null;
        //get the used ids from the KB node, setting up empty containers if we need to initialize it
        if (rotationNode) {
            let mimData = rotationNode.data[this.mimId];
            if (!mimData) {
                mimData = rotationNode.data[this.mimId] = {};
            }
            usedPromptIds = mimData[promptSubCategory + '_' + index];
            //if it is an array, then it was data from the initial implementation and should be
            //wiped. Later, we can remove the || part of this check, and leave it as just a null
            //check
            if (!usedPromptIds || Array.isArray(usedPromptIds)) {
                usedPromptIds = mimData[promptSubCategory + '_' + index] = {};
            }
        }
        
        //go through the prompts, getting valid ones, and setting aside used ones
        for (let prompt of this.prompts) {
            if (prompt.promptCategory === PROMPT_CATEGORY_ERROR &&
                prompt.promptSubCategory === promptSubCategory &&
                prompt.index === index) {
                
                prompts.push(prompt);
            }
        }
        //get a prompt if we can
        result = selectItem(prompts, (prompt) => {
            return this.promptMeetsCondition(prompt, promptData);
        }, usedPromptIds);
        return result;
    }

    private promptMeetsCondition(prompt:MimPrompt, promptData:vm.Context):boolean {
        if (!promptData || !prompt.condition) {
            return true;
        }

        //zero or negative weights should be interpreted as 'never pick this prompt'
        if (prompt.weight && prompt.weight <= 0) {
            return false;
        }

        //remove the leading '${' and trailing '}' from the condition string, because
        //we don't want those - older mims may have been created with them present
        let condition = prompt.condition.replace(/^\$\{/, "").replace(/\}$/, "");
        //do a safe eval on the condition
        try {
            return !!vm.runInContext(condition, promptData);
        } catch (e) {
            console.error(`error evaluating prompt condition: ${prompt.condition} - error: ${e.message}`);
            return false;
        }
    }

    private addPromptWithJSON(data):void {
        this.prompts.push(new MimPrompt(data));
    }
    
    private getSandbox(promptData:any):vm.Context {
        if (!this.vmContext) {
            this.vmContext = vm.createContext(promptData);
        }
        return this.vmContext;
    }
}
