import * as path from 'path';
import {Plugin, PluginCallback} from 'jibo-plugins';
import * as animdb from 'jibo-anim-db';
import Runtime from '../Runtime';

/**
 * Installs the AnimDB API, which can be found in the "jibo-anim-db" module
 * @class AnimDBPlugin
 * @implements Plugin
 * @private
 */
class AnimDBPlugin implements Plugin {

    api = animdb.api;

    init(done:PluginCallback): void {
        const jibo = Runtime.instance;
        // Attempt to find jibo-anim-db-animations project
        let rootPath = jibo.utils.PathUtils.resolve('jibo-anim-db-animations');
        let promise: Promise<any>;
        let animDBPath: string;
        if (!rootPath) {
            console.warn(`Module 'jibo-anim-db-animations' not found. AnimDB plugin will not contain animations.`);
            promise = animdb.api.init(jibo);
        } else {
            animDBPath = path.join(path.dirname(rootPath), 'animdb.json');
            promise = animdb.api.init(jibo, animDBPath);
        }
        promise.then(() => done())
            .catch(err => {
                console.error(`Error parsing AnimDB at path: '${animDBPath}':`, err);
                done();
            });
    }
}

// register it as a jibo plugin
Runtime.registerPlugin(AnimDBPlugin, 'anim-db', {
    depends: ['anim-utils'],
    api: true,
    name: 'animDB'
});

export default AnimDBPlugin;
