/**
 * @typedef jibo.lps.identity#Person
 * @description Interface of elements of a recognized Person Entity
 * @prop {String} id UUID of LPS system mapping to entity, including looper ID if recognized.
 * @prop {String} type Type of entity recognized.
 */
export interface Person{
    id: string;
    type: SensoryType | IDLabels | PresenceType;
}

// Todd might have these separately
/**
 * @typedef jibo.lps.identity#IDLabels
 * @description Possible ID status labels for entities.
 * @prop {String} NOT_ENROLLED Speaker is definitely not enrolled.
 * @prop {String} ANYBODY Speaker could or could not be enrolled.
 * @prop {String} IDENTIFIED Speaker is in the loop and identified.
 */
export enum IDLabels {
    NOT_ENROLLED = <any> "NOT_ENROLLED",
    ANYBODY = <any> "ANYBODY",
    IDENTIFIED = <any> "IDENTIFIED"
};
/**
 * @typedef jibo.lps.identity#SensoryType
 * @description Possible sensory types.
 * @prop {String} AUDIO_LOCALIZATION Audio Input
 * @prop {String} MOTION Motion input
 * @prop {String} VISION Visual Input
 * @prop {String} WAKE Any input that woke Jibo
 * @prop {String} GROUND_TRUTH Ground truth input to LPS
 * @intdocs
 */
export enum SensoryType {
    AUDIO_LOCALIZATION = <any> "audio_localization",
    MOTION = <any> "motion",
    PERSON = <any> "person",
    WAKE = <any>  "wake",
    GROUND_TRUTH = <any> "ground_truth"
};
/**
 * @typedef jibo.lps.identity#PresenceType
 * @description Possible presence inputs.
 * @prop {String} VOICE Voice Input
 * @prop {String} FACE Face input
 * @intdocs
 */
export enum PresenceType {
    VOICE = <any> "voice",
    FACE = <any> "face"
};
/**
 * @typedef jibo.lps.identity#PresenceEventData
 * @description Presence event data input
 * @prop {String} reason Reason for presence input
 */
export interface PresenceEventData {
    reason:string;
}
/**
 * @typedef jibo.lps.identity#IDEventData
 * @description Reason data extension for reason for ID event
 * @prop {String} Reason reason for event
 */
export interface IDEventData extends Person {
    reason:string;
}
