import Runtime from '../../Runtime';
import {MediaService, CameraID, PhotoType} from './MediaService';
export {MediaService, CameraID, PhotoType} from './MediaService';
import {MediaManagerService} from './MediaManagerService';
import MediaModel from './MediaModel';
import MediaNode from './MediaNode';
// import {RegistryClient} from 'jibo-client-framework';
import {isInitialized, promisify} from '../../utils/decorators';

import Log = require('jibo-log');
const log = new Log('Media');

interface TakePhotoParams {  // defaults:
    camera?:CameraID;      // CameraID.RIGHT
    photoType?:PhotoType;  // PhotoType.SNAP
    undistort?:boolean;    // true
}

interface TakePhotoResponse {
    id:string;
    url:string;
}

interface StorePhotoParams {
    id?:string;
    buffer?:Buffer;
}

interface StorePhotoResponse {
    id:string;
    url:string;
    thumbnails:ThumbnailsResponse;
}

interface ThumbnailsResponse {
    [name:string]:string;  // uuid for each thumbnail
}

interface Thumbnails {
    [name:string]:[number, number];
}

/**
 * @typedef jibo.media#ThumbnailType
 * @description Enum of thumbnail types
 * @property thumb {any} Mobile
 * @property thumb_robot {any} Robot
 */
export enum ThumbnailType {
    thumb       = <any>'thumb',       // mobile
    thumb_robot = <any>'thumb_robot'  // robot
};

interface ViewfinderParams {
    enabled?:boolean;  // Turn preview viewport on or off
    camera?:CameraID;  // One of 0, 1; signifying camera id
    width?:number;     // viewfinder width in pixels
    height?:number;    // viewfinder height in pixels
    x?:number;         // top edge of viewfinder location in pixels
    y?:number;         // right edge of viewfinder location in pixels
}

interface ViewfinderResponse extends ViewfinderParams {
    ts: [number, number];
}

type ErrCallback = (err?:Error) => void;

/** Callback for {@link jibo.media#takePhoto}.
 *
 * ```
 * jibo.media.takePhoto((err, data) => {
 *     if(!err) {
 *         let img = new Image();
 *         img.src = data.url;
 *     }
 *     else {
 *         console.error(err);
 *     }
 * });
 * ```
 *
 * @callback jibo.media~TakePhotoCallback
 * @param [error] {Error|null} An error object if there was an error, or `null`.
 * @param data {object} Data about the photo.
 * @param data.id {string} Content ID of temporary in-memory preview photo.
 * @param data.url {string} URL to retreive temporary in-memory preview photo.
 */
type TakePhotoCallback = (err:Error, response?:TakePhotoResponse) => void;

/** Callback for {@link jibo.media#storePhoto}.
 *
 * @callback jibo.media~StorePhotoCallback
 * @param [error] {Error} error `null` if there is no error.
 * @param [result] {object} The object's keys correspond to the
 * thumbnail keys provided in the `thumbnails` argument of
 * `storePhoto`.  Values are the photo id as assigned by the media
 * service. Use `getPhoto` to retrieve the PIXI.Texture that
 * corresponds to this photo, or `getUrl` to get the url as served by
 * the media service.
 */
type StorePhotoCallback = (err:Error, response?:StorePhotoResponse) => void;

type ViewfinderCallback = (err:Error, response?:ViewfinderResponse) => void;


/** Media API - jibo.media
 *
 * ```
 * let params = {camera: jibo.media.CameraID.LEFT};
 * jibo.media.takePhoto(params, (err, data) => {
 *     jibo.loader.load({src: data.url, format: 'binary'}, (error, buffer) => {
 *          jibo.media.storePhoto(
 *             buffer,
 *             (error, result) => {
 *                let thumbnailId = result.thumbnails[jibo.media.ThumbnailType.thumb_robot];
 *                jibo.media.getPhoto(thumbnailId, (err, pixiTexture) => {
 *                   const s = new PIXI.Sprite();
 *                   s.texture = pixiTexture;
 *                   jibo.face.stage.addChild(s);
 *                })
 *          });
 *     });
 * });
 *
 * ```
 * You can use Promises instead of callbacks by simply omitting the callback.
 * ```
 * let params = {photoType: jibo.media.CameraID.PREVIEW};
 * jibo.media.takePhoto(params)
 *     .then( (data) => {
 *          return jibo.media.storePhoto(data.id);
 *     })
 *     .then( (result) => {
 *         let thumbnailId = result.thumbnails[jibo.media.ThumbnailType.thumb_robot];
 *         return jibo.media.getPhoto(thumbnailId);
 *     .then( (pixiTexture) => {
 *         const s = new PIXI.Sprite();
 *         s.texture = pixiTexture;
 *         jibo.face.stage.addChild(s);
 *     });
 * });
 * ```
 *
 * @namespace jibo.media
 */
export class Media {
    public CameraID: typeof CameraID;
    public PhotoType: typeof PhotoType;
    public ThumbnailType: typeof ThumbnailType;
    public mediaService:MediaService;
    public mediaManagerService:MediaManagerService;
    private proxyUrl:string;
    private isInitialized:boolean = false;


    constructor() {
        this.CameraID = CameraID;
        this.PhotoType = PhotoType;
        this.ThumbnailType = ThumbnailType;
        this.mediaService = new MediaService();
        this.mediaManagerService = new MediaManagerService();
    }


    init(callback) {
        //was having trouble getting this new method to work (or even appear) for skills in the simulator:
        // RegistryClient.instance.getRecordByName('media-proxy', (err, record) => {
            // if (err) {
            //     callback(err);
            // } else {
            //     this.proxyUrl = `http://${record.host}:${record.port}`;
            //     this.isInitialized = true;
            //     callback();
            // }
        // });
        // so we will do this instead:
        let records = Runtime.instance.records;
        for (let i=0; i<records.length; i++) {
            //if (records[i].name === 'media-manager') {  // TODO someday we can just have one service name for this
            if (records[i].name === 'media-proxy') {
                let record = records[i];
                this.proxyUrl = `http://${record.host}:${record.port}`;
                break;
            }
        }
        if (this.proxyUrl) {
            log.info('proxyUrl', this.proxyUrl);
        } else {
            log.error('could not find media-manager service');
        }

        let kb = Runtime.instance.kb;
        kb.registerModelClass('jibo/media', MediaModel);
        kb.registerNodeClass('media', MediaNode, 'jibo/media');
        kb.media = <any>kb.createModel('/jibo/media');

        // we mark as inited even if 'media-proxy' isn't found to make it
        // more backward-campatable with old SSMs (though this might be futile)
        this.isInitialized = true;
        process.nextTick(callback);
    }


    /** Take a photo. Returns data about photo including the content
     * id and url to the temporary in-memory copy of the photo.
     *
     * @method jibo.media#takePhoto
     * @param [params] {object} Optional parameters object.
     * @param [params.camera=jibo.media.CameraID.RIGHT] {jibo.media.CameraID}
     * Which camera to use, left or right.
     * @param [params.photoType=jibo.media.PhotoType.FULL] {jibo.media.PhotoType}
     * Size/type of photo to take.
     * @param [params.undistort=true] {boolean} Undistort (flatten)
     * the photo. If `false` image will have fish-eye distortion.
     * @param [callback] {jibo.media~TakePhotoCallback} Called with an
     * error, or with data about the photo including the content ID
     * (`data.id`). If callback is omitted a promise is returned
     * instead.
     * @returns {Promise} A promise that resolves when the operation is
     * finished.
     */
    public takePhoto(callback:TakePhotoCallback);
    public takePhoto():Promise<TakePhotoResponse>;
    public takePhoto(params:TakePhotoParams, callback:TakePhotoCallback);
    public takePhoto(params:TakePhotoParams):Promise<TakePhotoResponse>;
    @promisify
    @isInitialized
    public takePhoto(params?, callback?):void|Promise<TakePhotoResponse> {
        // line up the arguments
        if (typeof params === 'function') {  // just callback given
            callback = params as TakePhotoCallback;
            params = {};
        }

        let camera = params.camera;
        if (camera !== undefined && camera !== CameraID.LEFT && camera !== CameraID.RIGHT) {
            camera = undefined;
        }
        if (camera === undefined) {
            camera = CameraID.RIGHT;  // default
        }

        let photoType = params.photoType;
        if (photoType !== undefined && (params.photoType < PhotoType.DEBUG || params.photoType > PhotoType.FOUR_MP)) {
            photoType = undefined;
        }
        if (photoType === undefined) {
            params.photoType = PhotoType.SNAP;  // default
        }

        let undistort = params.undistort;
        if (undistort === undefined) {
            undistort = true;  // default
        } else {
            undistort = !!undistort;  // force it to boolean
        }

        let store = false;
        this.mediaService.takePhoto(camera, photoType, undistort, store, (err, data) => {
            if (err) {
                callback(err);
            } else {
                let response:TakePhotoResponse = {
                    id: data.id,
                    url: this.getPreviewUrl(data.id)
                };
                callback(null, response);
            }
        });
    }


    /** Save a temporary in-memory photo via the content id returned
     * from `takePhoto`, or via a buffer object. Photo will be saved
     * locally to disk and in the cloud. Default thumbnails (`thumb`
     * for mobile, and `thumb_robot` for Jibo) will be generated and
     * also saved. The KB media list `jibo.kb.media` will also be
     * updated. Data including the content id and url is provided.
     *
     * @method jibo.media#storePhoto
     * @param [id] {string} Content id of in-memory recently taken
     * photo to be stored. Can also be specified via `params.id`.
     * @param [buffer] {Buffer} Instead of providing an id, an image
     * in a buffer object to store. Can also be specified via
     * `params.buffer`.
     * @param [params] {object} Optional parameters object.
     * @param [params.id] {string} Content id of in-memory recently taken photo to be stored.
     * @param [params.buffer] {Buffer} An image in a buffer object to be stored.
     * @param [callback] {jibo.media~StorePhotoCallback} Called when
     * photos are stored. If callback is omitted a promise is returned
     * instead.
     * @returns {Promise} A promise that resolves when the operation is
     * finished.
     */
    public storePhoto(id:string, callback:StorePhotoCallback);
    public storePhoto(id:string):Promise<StorePhotoResponse>;
    public storePhoto(id:string, params:StorePhotoParams, callback:StorePhotoCallback);
    public storePhoto(id:string, params:StorePhotoParams):Promise<StorePhotoResponse>;
    public storePhoto(buffer:Buffer, callback:StorePhotoCallback);
    public storePhoto(buffer:Buffer):Promise<StorePhotoResponse>;
    public storePhoto(buffer:Buffer, params:StorePhotoParams, callback:StorePhotoCallback);
    public storePhoto(buffer:Buffer, params:StorePhotoParams):Promise<StorePhotoResponse>;
    public storePhoto(params:StorePhotoParams, callback:StorePhotoCallback);
    public storePhoto(params:StorePhotoParams):Promise<StorePhotoResponse>;
    @promisify
    @isInitialized
    public storePhoto(one, two?, three?):void|Promise<StorePhotoResponse> {
        let id;
        let buffer;
        let params;
        let callback;
        // line up the arguments
        if (typeof one === 'string' || one instanceof Buffer) {
            // id|buffer, ?, ?
            if (one instanceof Buffer) {
                buffer = one;
            } else {
                id = one;
            }
            if (typeof two === 'function') {
                // id|buffer, callback
                params = {};
                callback = two as StorePhotoCallback;
            } else {
                // id|buffer, params, callback
                params = two;
                callback = three;
            }
        } else {
            // params, callback
            params = one;
            callback = two;
        }

        // id or buffer can be optionally be specified in params
        id = id || params.id;
        buffer = buffer || params.buffer;

        if ((!buffer && !id) || (id && buffer)) {
            throw new Error('storePhoto requires either id or buffer');
        }

        // generate mobile and robot thumbnails
        // user can't currently specify anything about thumbnails
        let thumbnails:Thumbnails = {};
        thumbnails[ThumbnailType.thumb]       = [720, 405];  // mobile
        thumbnails[ThumbnailType.thumb_robot] = [330, 330];  // robot

        let timer = performance.now();
        this.mediaService.storePhoto(buffer, id, thumbnails, (err, data) => {
            if (err) {
                callback(err);
            } else {
                Runtime.instance.kb.media.storePhoto(data, (err, response) => {
                    let elapsed = Math.round(performance.now() - timer);
                    console.warn('storePhoto total time took '+elapsed+'ms');
                    callback(err, response);
                });
            }
        });
    }


    /** Delete a photo from the local image store and from the cloud.
     *
     * @method jibo.media#deletePhoto
     * @param id {string} Content ID of photo to delete.
     * @param [callback] {function} Called with err object if there
     * was an error. If callback is omitted a promise is returned instead.
     * @returns {Promise} A promise that resolves when the operation is
     * finished.
     */
    public deletePhoto(id:string, callback:ErrCallback);
    public deletePhoto(id:string):Promise<void>;
    @promisify
    public deletePhoto(id:string, callback?:ErrCallback):void|Promise<void> {
        let immediate = true;
        let deleteLocal = true;
        let deleteRemote = false;  // let the MediaListManager take care of this in the background
        let mediaType = this.mediaManagerService.MediaType.image;
        let timer = performance.now();
        this.mediaManagerService.delete(id, immediate, deleteLocal, deleteRemote, mediaType, (err) => {
            if (err) {
                log.iferr(err);
                callback(err);
            } else {
                // do the kb update parts, and the cloud deleting in the background
                Runtime.instance.kb.media.deletePhoto(id, (err) => {
                    let elapsed = Math.round(performance.now() - timer);
                    log.warn('local deletePhoto took '+elapsed+'ms');
                    callback();
                });
            }
        });
    }


    /** Retrieve the PIXI.Texture that corresponds to the specified photo.
     *
     * @method jibo.media#getPhoto
     * @param id {string} The photo ID to retrieve the texture for.
     * @param [callback] {function} Node style callback that returns a
     * `PIXI.Texture`. If callback is omitted a promise is returned
     * instead.
     * @returns {Promise} A promise that resolves when the operation
     * is finished.
     */
    public getPhoto(id:string, callback:(err:Error, image?:PIXI.Texture) => void);
    public getPhoto(id:string):Promise<PIXI.Texture>;
    @promisify
    @isInitialized
    public getPhoto(id:string, callback?:(err:Error, image?:any) => void):void|Promise<PIXI.Texture> {
        let url = this.getUrl(id);
        Runtime.instance.loader.load({
            format: 'image',
            src: url,
            type: 'texture'
        }, callback);
    }


    /** Get a URL given a photo ID.
     *
     * @method jibo.media#getUrl
     * @param id {string} Content ID of the photo.
     * @returns {string} URL to the photo.
     */
    public getUrl(contentId:string):string {
        // points at the media-proxy which makes sure the photo
        // has been downloaded before serving up the photo
        return `${this.proxyUrl}/proxy/media/photo/get?id=${contentId}`;
    }


    /** Get the preview URL of a recently taken
     * in-memory photo that hasn't been stored yet.
     *
     * @method jibo.media#getPreviewUrl
     * @param id {string} Content ID of the photo.
     * @returns {string} URL to the photo.
     */
    public getPreviewUrl(id:string):string {
        return this.mediaService.getPreviewUrl(id);
    }


    /** Set up a viewfinder in a window with camera preview positioned
     * at a given location on-screen.
     *
     * @method jibo.media#setViewfinder
     * @param [enable=false] {boolean} Show (enable) or hide
     * viewfinder. Can also be specified via `params.enabled`.
     * @param [params] {object} Optional parameters object.
     * @param [params.enable=false] {boolean} Show (enable) or hide
     * viewfinder.
     * @param [params.width=1280] {number} Width of the viewfinder in pixels.
     * @param [params.height=720] {number} Height of the viewfinder in pixels.
     * @param [params.x=0] {number} X-coordinate for placing the viewfinder. In pixels.
     * @param [params.y=0] {number} Y-coordinate for placing the viewfinder. In pixels.
     * @param [callback] {function} Callback for the method. If callback
     * is omitted a promise is returned instead.
     * @returns {Promise} A promise that resolves when the
     * operation is finished.
     */
    public setViewfinder(enable:true|false, callback:ErrCallback);
    public setViewfinder(enable:true|false):Promise<void>;
    public setViewfinder(enable:true, params:ViewfinderParams, callback:ErrCallback);
    public setViewfinder(enable:true, params:ViewfinderParams):Promise<void>;
    public setViewfinder(params:ViewfinderParams, callback:ErrCallback);
    public setViewfinder(params:ViewfinderParams):Promise<void>;
    @promisify
    @isInitialized
    public setViewfinder(one, two?, three?):void|Promise<void> {
        let enable;
        let params;
        let callback;
        if (one !== null && typeof one === 'object') {
            // params, callback
            params = one as ViewfinderParams;
            callback = two as ErrCallback;
            enable = params.enable;
        } else if (!three && typeof two === 'function') {
            // enable, callback
            enable = one;
            callback = two as ErrCallback;
            params = {};
        } else {
            // enable, params, callback
            enable = one;
            params = two as ViewfinderParams;
            callback = three as ErrCallback;
        }

        let assignIfDefined = (source, target, keys) => {
            keys.forEach( (key) => {
                if (source[key] !== undefined) {
                    target[key] = source[key];
                }
            });
        };

        // enable argument has higher precedence than params.enable
        // and that is taken care of above
        let data = {enable: enable};
        assignIfDefined(params, data, ['camera', 'height', 'width', 'x', 'y']);

        this.mediaService.setViewfinder(data, callback);
    }


    /** Get the current state of the viewfinder preview window.
     *
     * @method jibo.media#getPreview
     * @param [callback] {function} Callback for the function that
     * returns an error, or if request is successful returns object
     * with timestamp, enabled, and window. If callback is omitted a
     * promise is returned instead.
     * @returns {Promise} A promise that resolves when the
     * operation is finished.
     */
    public getViewfinder(callback:ViewfinderCallback);
    public getViewfinder():Promise<ViewfinderResponse>;
    @promisify
    @isInitialized
    public getViewfinder(callback?:ViewfinderCallback):void|Promise<ViewfinderResponse> {
        this.mediaService.getViewfinder(callback);
    }
}


export default Media;
