/**
 * Schedule a job to run on the robot in the background.
 * @namespace jibo.scheduler
 * @intdocs
 */


/**
 * Class to schedule a job with the Skills Service Manager.
 * @class SchedulerService
 * @intdocs
 * @memberof jibo.scheduler
 */


declare type SkillData = {
    skill:string;
    domain:string;
    intent:string;
};

class SchedulerService {

    private _httpInterface:string = null;
    private _initialized:boolean = false;


    /**
     * Initialize the performance module for `jibo.init`.
     * @method jibo.scheduler.SchedulerService#init
     * @param service {Object} The service options
     * @param service.host {String} host name
     * @param service.port {String} port number
     * @param callback {Function} callback
     * @intdocs
     */
    public init(service:{host:string; port:string}, callback:(err?:Error) => void):void {
        this._httpInterface = "http://" + service.host + ":" + service.port;
        this._initialized = true;
        callback();
    }

    /**
     * Trigger an instant ota-update (check for updates, download and install)
     * @method jibo.scheduler.SchedulerService#otaDownloadAndInstall
     * @param callback {Function} callback
     * @intdocs
     */
    public otaDownloadAndInstall(callback:(err?:Error) => void):void {
        this._sendRequest('/ota-update', callback);
    }

    /**
     * Get the current state of a scheduled OTA download
     * @method jibo.scheduler.SchedulerService#otaDownloadStatus
     * @param callback {Function} callback
     * @intdocs
     */
    public otaDownloadStatus(callback:(err:Error, response?:any) => void):void {
        if(!this._initialized) {
            return callback(new Error('Scheduler Service not initialized.'));
        }

        let request:XMLHttpRequest = new XMLHttpRequest();
        request.open("POST", this._httpInterface + '/download-status', true);
        request.onreadystatechange = () => {

            // request is complete
            if(request.readyState === 4) {
                let response = null;
                try {
                    response = JSON.parse(request.response);
                }
                catch(e) {
                    return callback(new Error('Response is not JSON. Timed out?'));
                }

                // "OK" status
                if(request.status === 200) {
                    callback(null, response.data);
                }
                else {
                    // failure if anything else
                    callback(new Error(response.message));
                }
            }
        };
        request.send();
    }

    /**
     * Add a job to the scheduler service.
     * @method jibo.scheduler.SchedulerService#addJob
     * @param schedule {String} The schedule (crontab syntax).
     * @param data {Object} Options for the skill redirect request.
     * @param callback {Function} callback
     * @intdocs
     */
    public addJob(schedule:string, skillData:SkillData, callback:(err:Error, jobId?:string) => void):void {
        if(!this._initialized) {
            return callback(new Error('Scheduler Service not initialized.'));
        }

        let request:XMLHttpRequest = new XMLHttpRequest();
        request.open("POST", this._httpInterface + '/add', true);
        request.onreadystatechange = () => {
            // request is complete
            if(request.readyState === 4) {
                let response = null;
                try {
                    response = JSON.parse(request.response);
                }
                catch(e) {
                    return callback(new Error('Response is not JSON. Timed out?'));
                }

                // "OK" status
                if(request.status === 200) {
                    callback(null, response.job);
                }
                else {
                    // failure if anything else
                    callback(new Error(response.message));
                }
            }
        };
        request.send(JSON.stringify({
            schedule,
            skillData
        }));
    }

    /**
     * Remove a job from the scheduler service.
     * @method jibo.scheduler.SchedulerService#removeJob
     * @param job {String} The ID of the job to remove.
     * @param callback {Function} callback
     * @intdocs
     */
    public removeJob(jobId:string, callback:(err?:Error) => void):void {
        if(!this._initialized) {
            return callback(new Error('Scheduler Service not initialized.'));
        }

        let request:XMLHttpRequest = new XMLHttpRequest();
        request.open("POST", this._httpInterface + '/remove', true);
        request.onreadystatechange = () => {
            // request is complete
            if(request.readyState === 4) {
                let response = null;
                try {
                    response = JSON.parse(request.response);
                }
                catch(e) {
                    return callback(new Error('Response is not JSON. Timed out?'));
                }

                // "OK" status
                if(request.status === 200) {
                    callback(null);
                }
                else {
                    // failure if anything else
                    callback(new Error(response.message));
                }
            }
        };
        request.send(JSON.stringify({jobId}));
    }

    /**
     * List all active jobs from the scheduler service.
     * @method jibo.scheduler.SchedulerService#listJobs
     * @param callback {Function} callback
     * @intdocs
     */
    public listJobs(callback:(err:Error, list?:any) => void):void {
        if(!this._initialized) {
            return callback(new Error('Scheduler Service not initialized.'));
        }

        let request:XMLHttpRequest = new XMLHttpRequest();
        request.open("POST", this._httpInterface + '/list', true);
        request.onreadystatechange = () => {
            // request is complete
            if(request.readyState === 4) {
                let response = null;
                try {
                    response = JSON.parse(request.response);
                }
                catch(e) {
                    return callback(new Error('Response is not JSON. Timed out?'));
                }

                // "OK" status
                if(request.status === 200) {
                    callback(null, response.jobs);
                }
                else {
                    // failure if anything else
                    callback(new Error(response.message));
                }
            }
        };
        request.send();
    }

    /**
     * Check if a specific job exists with the scheduler service; returns current job data if it exists.
     * @method jibo.scheduler.SchedulerService#hasJob
     * @param jobId {String} The ID of the job to check for.
     * @param callback {Function} callback
     * @intdocs
     */
    public hasJob(jobId:string, callback:(err:Error, data?:any) => void):void {
        if(!this._initialized) {
            return callback(new Error('Scheduler Service not initialized.'));
        }

        let request:XMLHttpRequest = new XMLHttpRequest();
        request.open("POST", this._httpInterface + '/has-job', true);
        request.onreadystatechange = () => {
            // request is complete
            if(request.readyState === 4) {
                let response = null;
                try {
                    response = JSON.parse(request.response);
                }
                catch(e) {
                    return callback(new Error('Response is not JSON. Timed out?'));
                }

                // "OK" status
                if(request.status === 200) {
                    callback(null, response.jobData);
                }
                else {
                    // failure if anything else
                    callback(new Error(response.message));
                }

            }
        };
        request.send(JSON.stringify({jobId}));
    }

    private _sendRequest(url:string, callback:(err?:Error) => void):void {
        if(!this._initialized) {
            return callback(new Error('Scheduler Service not initialized.'));
        }

        let request:XMLHttpRequest = new XMLHttpRequest();
        request.open("POST", this._httpInterface + url, true);
        request.onreadystatechange = () => {

            // request is complete
            if(request.readyState === 4) {
                let response = null;
                try {
                    response = JSON.parse(request.response);
                }
                catch(e) {
                    return callback(new Error('Response is not JSON. Timed out?'));
                }

                // "OK" status
                if(request.status === 200) {
                    callback(null);
                }
                else {
                    // failure if anything else
                    callback(new Error(response.message));
                }
            }
        };
        request.send();
    }
}

export default SchedulerService;
