import {EventEmitter} from 'events';

interface SubscriptionObject {
    // the highest priority error in the error service (null if no errors remaining)
    nextErrorId:string;
    // the error id which was subscribed to
    subscribedErrorId:string;
    // true if the error is no longer in the priority queue or the rescheduler
    // false otherwise
    resolved:boolean;
}

interface ProcessedErrorObject {
    // returns as true if the error code passed in matches the currently active error in the SSM error service
    // false otherwise
    processedError:boolean;
}

/**
 * Class to interface with the Error Service in the Skills Service Manager
 * @class ErrorService
 * @private
 * @memberof jibo.errors
 */
class ErrorService extends EventEmitter {
    private _httpInterface:string;
    private _wsInterface:string;
    private _initialized:boolean;

    // a callback to fire when the subscribed error is no longer the highest priority error
    private _subscribeErrorCallback:(error:Error, subscriptionObj: SubscriptionObject)=>void = null;
    private _subscribeErrorHttpRequest: { request: XMLHttpRequest, data:any } = { request: null, data: null };

    constructor() {
        super();

        this._httpInterface = null;
        this._wsInterface = null;
        this._initialized = false;
        this._subscribeErrorCallback = null;
    }

    public get ErrorStatus() {
        return {
            ABORTED: "ABORTED",
            NETWORK_ERROR: "NETWORK_ERROR",
            DATA_ERROR: "DATA_ERROR"
        };
    }

    /**
     * Initialize the error service module for `jibo.init`.
     * @method jibo.errors.ErrorService#init
     * @param service {Object} The service options
     * @param service.host {String} host name
     * @param service.port {String} port number
     * @param callback {Function} callback
     */
    public init(service:{host:string; port:string}):void {
        this._httpInterface = "http://" + service.host + ":" + service.port;
        this._wsInterface = "ws:" + service.host + ":" + service.port;
        this._initialized = true;
    }

    /**
     * Get the id for the current error or null if there is no error active
     * @method jibo.errors.ErrorService#getCurrentErrorId
     * @param callback {Function} The callback which returns either an error or the currentErrorId (null if no active error)
     */
    public getCurrentErrorId(callback:(err:Error, currentErrorId:string)=>void): void {
        this._sendMessage('/getCurrentErrorId', {}, (err, response)=>{
            if(err) {
                callback(err, null);
            } else if(!response.hasOwnProperty('currentErrorId')) {
                callback(new Error("Malformed json: no current error id returned from error service"), null);
            } else {
                callback(null, response.currentErrorId);
            }
        });
    }

    /**
     * Get how many errors are currently entered in the error service priority queue.
     * This includes the current error
     * @method jibo.errors.ErrorService#getErrorCount
     * @param callback {Function} The callback which returns either an error or the number of errors
     */
    public getErrorCount(callback:(err:Error, numErrors:number)=>void): void {
        this._sendMessage('/getErrorCount', {}, (err, response)=>{
            if(err) {
                callback(err, null);
            } else if(!response.hasOwnProperty('errorCount')) {
                callback(new Error("no error count returned from error service"), null);
            } else {
                callback(null, response.errorCount);
            }
        });
    }

    /**
     * Subscribe to an error to get notified when your subscribed error is not / no longer the current error in the error service
     * @method jibo.errors.ErrorService#subscribeError
     * @param errorCode {string} The support error id string to subscribe to
     * @param callback {Function} The callback which fires if the error is no longer the current error in the error service
     *                              Passes an error as a parameter if a server side error occurs
     *                              This callback is called either when:
     *                              1) the error gets resolved from the SSM Error Service (and removed from the priority queue)
     *                              2) one error is subscribed and then another error subscribes
     *                              3) the error is not present in the SSM Error Service priority queue (in which case it will resolve right away)
     *                              4) the client called processedError on the error it's subscribed to
     */
    public subscribeError(errorCode:string, callback:(error:Error, subscriptionObj: SubscriptionObject)=>void): void {
        // only subscribe to one error at a time (overwrite the previous subscription callback and abort the previous request)
        // this prevents race conditions where subscribing to two errors in rapid succession may cause
        // the first error to fire the onResolved callback.  this would be unideal to be able to resolve
        // multiple errors at once
        if(this._subscribeErrorHttpRequest.request) {
            this._subscribeErrorHttpRequest.request.abort();
        }
        this._subscribeErrorHttpRequest.data = errorCode;
        this._subscribeErrorHttpRequest.request = this._sendMessage('/subscribeError', { errorCode: errorCode }, (err, response)=>{
            // we can safely set this to null here because in the case of an abort, this callback will fire before the the next request is assigned
            this._subscribeErrorHttpRequest = { request: null, data: null };

            // generate an error if for some reason the error service SSM thinks we were subscribed to a different error than we originally passed in
            if(!err && response.subscribedErrorId !== errorCode) {
                let error = new Error(`Client subscribed to ${errorCode} but ErrorService subscribed to ${response.subscribedErrorId}`);
                error.name = this.ErrorStatus.DATA_ERROR;
                callback(error, null);
            } else {
                callback(err, response);
            }
        });
    }

    /**
     * Mark an error for being processed in the SSM error service. This will move the error to the error rescheduler.
     * The error will be removed from the error rescheduler if it is internally resolved.
     * If the error is not internally resolved, the error rescheduler will reinsert the error into the priority queue (which may trigger the settings skill to relaunch)
     * @method jibo.errors.ErrorService#processedError
     * @param errorCode {string} The support error id string to process
     * @param callback {Function} The callback which fires indicating the SSM error service has attempted to move the error to the error rescheduler
     *                              The processedErrorObject field returns along with an error object
     *                              This error object in the callback is populated if the error code is ommitted or if there is a communication problem with the SSM error service.
     *                              If the error object is populated, the response data object will be null and vice versa
     */
    public processedError(errorCode:string, callback:(error:Error, processedErrorObject: ProcessedErrorObject)=>void): void {
        this._sendMessage('/processedError', { errorCode: errorCode }, (err, response)=>{
            let processedError = (!err) ? response.processedError : false;

            callback(err, {
                processedError: processedError
            });
        });
    }

    private _sendMessage(path:string, data: any, cb:(err:Error, response:any)=>void): XMLHttpRequest {
        let requestPath = this._httpInterface + path;
        let request:XMLHttpRequest = new XMLHttpRequest();
        request.open("POST", requestPath, true);
        // request is complete
        request.onload = () => {
            let response = "";
            try {
                response = JSON.parse(request.response);
            } catch(ex) {
                cb(new Error(`Server sent back invalid json: ${request.response}, exception: ${ex}`), null);
                return;
            }
            cb(null, response);
        };
        request.onabort = ()=>{
            let error = new Error(`request aborted for path: ${requestPath} with data: ${JSON.stringify(data)}`);
            error.name = this.ErrorStatus.ABORTED;
            cb(error, null);
        };
        request.onerror = ()=>{
            let error = new Error(`request failed for path: ${requestPath} with data: ${JSON.stringify(data)}`);
            error.name = this.ErrorStatus.NETWORK_ERROR;
            cb(error, null);
        };
        request.send(JSON.stringify(data));
        return request;
    }
}

export default ErrorService;
