import Runtime from '../Runtime';
import {Plugin, PluginCallback} from 'jibo-plugins';
import {DOFArbiter, PriorityConfig} from 'jibo-dof-arbiter';


/**
 * Installs the DOF Arbiter API, which can be found in the "jibo-dof-arbiter" module
 * @class DOFArbiterPlugin
 * @implements Plugin
 * @private
 */
class DOFArbiterPlugin implements Plugin {

	api:DOFArbiter;
	arbitrationPolicyConfig: PriorityConfig = {
		priorityForUnknownLabels: 5,
		priorityForDirectUsers: 10,
		priorityEntries: [
			{owner: 'Attention', priority: 3},
			{owner: 'Behavior', priority: 5},
			{owner: 'EmbodiedSpeech', priority: 5},
			{owner: 'BargeIn', priority: 7},
			{owner: 'EmbodiedListen', priority: 7},
			{owner: 'AttentionCommand', priority: 7},
			{owner: 'Test', priority: 9}
		]
	};

	constructor() {
		this.api = new DOFArbiter();
	}

	init(done:PluginCallback): void {
		const animUtils = Runtime.instance.animate;
		this.api.init(animUtils, this.arbitrationPolicyConfig); // this depends on the animation utilities being fully initialized
		done();
	}
}

// register it as a jibo plugin
Runtime.registerPlugin(DOFArbiterPlugin, 'dof-arbiter', {
	depends: ['anim-utils'],
	api: true,
	name: 'dofArbiter'
});

export default DOFArbiterPlugin;
