import Runtime from '../Runtime';
import {Plugin, PluginCallback} from 'jibo-plugins';
import {AttentionManager} from 'jibo-attention-manager';


/**
 * Installs the Attention Manager API
 * @class AttentionPlugin
 * @implements Plugin
 * @private
 */
class AttentionPlugin implements Plugin {

	api:any;

	constructor() {
		// noop
	}

	init(done:PluginCallback): void {
		try {
			// We build the api and provide it asynchronously since
			// the AttentionManager constructor needs an initialized jibo instance
			this.api = new AttentionManager(Runtime.instance);
			done(null, this.api);
		}
		catch(e) {
			done(`Error initializing attention plugin: ${e}`);
		}
	}
}

// register it as a jibo plugin
Runtime.registerPlugin(AttentionPlugin, 'attention', {
	depends: ['anim-utils'],
	api: true,
	name: 'attention'
});

export default AttentionPlugin;
