import {EventContainer, EmitterMode, Event as TypedEvent } from 'jibo-typed-events';
import { GlobalEvent } from './GlobalEvent';
import {ListenResults, GlobalCommand, GlobalCommandMap, Callback} from 'jibo-common-types';
import { WSClient } from 'jibo-client-framework';
import JiboLog = require("jibo-log");


interface WSResponse {
    status:string;
    message:string;
    id:string;
    result: any;
    moreinfo:string;
};

class GlobalEvents extends EventContainer {
    public touchStop: GlobalEvent<boolean[]>;
    public voiceStop: GlobalEvent<ListenResults>;
    public help: GlobalEvent<ListenResults>;
    public sleep: GlobalEvent<ListenResults>;
    public pause: GlobalEvent<ListenResults>;
    public volume: GlobalEvent<ListenResults>;
    public whatCanIDo: GlobalEvent<ListenResults>;
    public holdOn: GlobalEvent<ListenResults>;
    public skillLaunch: TypedEvent<ListenResults>;
    public skillRelaunch: TypedEvent<ListenResults>;
    public eventsWithHandlers: Set<string>;

    private _globalSocket: WSClient;
    private _httpInterface: string;
    private voiceEvents:GlobalEvent<any>[];
    private eventHandlers: any;
    private log: JiboLog;

    constructor() {
        super();

        this.log = new JiboLog("global-events");
        /**
         * Set of names of all events that globalEvents currently has
         * subscribed handlers for
         * @name jibo.globalEvents#eventsWithHandlers
         * @type {Set<string>}
         */
        this.eventsWithHandlers = new Set<string>();
        /**
         * Global voice stop command received
         * @name jibo.globalEvents#voiceStop
         * @type {jibo.globalEvents.GlobalEvent<jibo.gl.ListenResults>}
         */
        this.voiceStop = new GlobalEvent<ListenResults>(GlobalCommand.STOP);
        /**
         * Received global help command
         * @name jibo.globalEvents#help
         * @type {jibo.globalEvents.GlobalEvent<jibo.gl.ListenResults>}
         */
        this.help = new GlobalEvent<ListenResults>(GlobalCommand.HELP);
        /**
         * Received global sleep command
         * @name jibo.globalEvents#sleep
         * @type {jibo.globalEvents.GlobalEvent<jibo.gl.ListenResults>}
         */
        this.sleep = new GlobalEvent<ListenResults>(GlobalCommand.SLEEP);
        /**
         * Received global pause command
         * @name jibo.globalEvents#pause
         * @type {jibo.globalEvents.GlobalEvent<jibo.gl.ListenResults>}
         */
        this.pause = new GlobalEvent<ListenResults>(GlobalCommand.PAUSE);
        /**
         * Received global volume command
         * @name jibo.globalEvents#volume
         * @type {jibo.globalEvents.GlobalEvent<jibo.gl.ListenResults>}
         */
        this.volume = new GlobalEvent<ListenResults>(GlobalCommand.VOLUME);
        /**
         * Received global whatCanIDo
         * @name jibo.globalEvents#whatCanIDo
         * @type {jibo.globalEvents.GlobalEvent<jibo.gl.ListenResults>}
         */
        this.whatCanIDo = new GlobalEvent<ListenResults>(GlobalCommand.WHATCANIDO);
        /**
         * Received global holdOn
         * @name jibo.globalEvents#holdOn
         * @type {jibo.globalEvents.GlobalEvent<jibo.gl.ListenResults>}
         */
        this.holdOn = new GlobalEvent<ListenResults>(GlobalCommand.HOLDON);
        /**
         * Received global skill launch
         * @name jibo.globalEvents#skillLaunch
         * @type {Event<jibo.gl.ListenResults>}
         */
        this.skillLaunch = new TypedEvent<ListenResults>('skill-launch');
        /**
         * Received global skill relaunch
         * @name jibo.globalEvents#skillRelaunch
         * @type {Event<jibo.gl.ListenResults>}
         */
        this.skillRelaunch = new TypedEvent<ListenResults>('skill-relaunch');
        /**
         * Received global touchStop event.
         * WARNING: this refers to the global `touchStop` event, which is
         * otherwise used to stop Jibo. If you want to listen for the
         * touch event but NOT clobber the stop behavior, please
         * refer to {@link jibo.system.SystemEvents#touchOn}.
         * @name jibo.globalEvents#touchStop
         * @type {jibo.globalEvents.GlobalEvent<boolean[]>}
         */
        this.touchStop = new GlobalEvent<boolean[]>('TOUCH');

        this.voiceEvents =  [
                        this.help,
                        this.voiceStop,
                        this.sleep,
                        this.pause,
                        this.whatCanIDo,
                        this.holdOn,
                        this.volume
                        ];
        this.setGlobalEvents();

        // only handle the global listeners for verbal global commands.
        this.eventHandlers = {
            'global': this.onGlobal.bind(this),
            'skill-launch': this.onSkillLaunch.bind(this),
            'skill-relaunch': this.onSkillRelaunch.bind(this),
        };
        this._initializeTouchListener();
    }

    public init(service : {host:string; port:number}, cb:Callback) {
        service.host = '127.0.0.1';
        const globalUrl =  "ws:" + service.host + ":" + service.port + "/globals";
        this._httpInterface = "http://" + service.host + ":" + service.port;
        this._globalSocket = new WSClient(globalUrl);

        this._globalSocket.on('error', (err) => {
            this.log.warn("error connecting to server ", err);
        });

        this._globalSocket.on('message', (data) => {
            this.onMessage(data);
        });

        cb();
    }

    /**
     * Announce to the skills service manager (SSM) if we can handle a specific global command.
     * @param {string} action Global action for the SSM to recognize.
     * @param {boolean} canHandle `true` if the `jibo` module can handle the global comand.
     * @method jibo.globalEvents#announceGlobalHandler
     */
    private announceGlobalHandler(action: GlobalCommand, canHandle: boolean) {
        this.log.info(`setting ${action} to ${canHandle}`);
        let body:any = {
            "action": action,
            "canHandle": canHandle,
        };
        let request = new XMLHttpRequest();
        body = JSON.stringify(body);
        request.open("POST", this._httpInterface + '/global', true);
        request.send(body);
        return;
    }

    /**
     * Announce to the skills service manager (SSM) if we can handle a specific global command.
     * @param {jibo.globalEvents.GlobalEvent[]} events Global events for the SSM to recognize.
     * @method jibo.globalEvents~setGlobalEvents
     * @intdocs
     */
    private setGlobalEvents() {
        this.voiceEvents.forEach((globalEvent:GlobalEvent<ListenResults>) => {
            globalEvent.setMode(EmitterMode.LAST_HANDLER);
            globalEvent.onNoListeners(() => {
                this.announceGlobalHandler(GlobalCommand[globalEvent.name], false);
                this.eventsWithHandlers.delete(globalEvent.name);
            });
            globalEvent.onAddedListener(() => {
                this.log.info("adding listener for ", globalEvent.name);
                this.eventsWithHandlers.add(globalEvent.name);
                this.announceGlobalHandler(GlobalCommand[globalEvent.name], true);
            });
        });
    }

    /**
     * We got a message from WS
     * @param {any} data Data from websocket message.
     * @method jibo.globalEvents~onMessage
     * @private
     */
    private onMessage(data) {
        if(data.status !== "OK") {
            this.log.warn("GlobalEvents returned status", data.status);
        }
        else {
            let handler = this.eventHandlers[data.message];
            if(handler) {
                handler(data);
            }
        }
    }

    /**
     * We got a message from WS
     * @param {WSResponse} data Data from websocket message.
     * @method jibo.globalEvents~onGlobal
     * @private
     */
    private onGlobal(data:WSResponse) {
        this.log.info("global data from ssm", data);
        let action:string = data.result.NLParse.intent;
        //there are a number of volume intents, so make sure we emit an event for all of them
        if (action.match(/^volume/)) {
            action = 'volume';
        }

        // actually emit the event!
        const event = this._getGlobalEvent(action);
        if(event) {
            this.log.info("accessing global", action, "command");
            event.emit(data);
        }
        else {
            this.log.error("No global event found:", action);
        }
        return;
    }

    /**
     * Called when ws with message 'skill-relaunch' is received.
     * @param {any} data JSON Data received from websocket.
     * @method jibo.globalEvents#onSkillRelaunch
     * @private
     */
    private onSkillRelaunch(data:WSResponse) {
        this.log.info("skill relaunch command from Global Service", data);
        this.skillRelaunch.emit(data.result);
    }

    /**
     * Called when ws with message 'skill-relaunch' is received.
     * @param {any} data JSON Data received from websocket.
     * @method jibo.globalEvents#onSkillRelaunch
     * @private
     */
    private onSkillLaunch(data:WSResponse) {
        this.skillLaunch.emit(data.result);
    }

    /**
     * Get the global event by the name of the event.
     * @param {string} eventName Name of the event to return.
     * @returns {jibo.globalEvents.GlobalEvent<any>} Global event to emit.
     * @method jibo.globalEvents~_getGlobalEvent
     * @intdocs
     */
    private _getGlobalEvent(eventName:string):GlobalEvent<any> {
        let event:GlobalEvent<any> = null;
        this.voiceEvents.forEach((globalEvent:GlobalEvent<ListenResults>) => {
            if (globalEvent.name === eventName || globalEvent.name === GlobalCommandMap.get(eventName)) {
                event = globalEvent;
            }
        });
        return event;
    }

    /**
     * Initialize the touch listener.
     * @method jibo.globalEvents~_initializeTouchListener
     * @private
     */
    private _initializeTouchListener():void {
        this.touchStop.setMode(EmitterMode.LAST_HANDLER);
    }
}

export default GlobalEvents;
