import Runtime from '../Runtime';
import {Plugin, PluginCallback} from 'jibo-plugins';

import {Media} from '../services/media/Media';

/**
 * Installs the Media API
 * @class MediaPlugin
 * @implements Plugin
 * @private
 */
class MediaPlugin implements Plugin {

    api:Media;

    constructor() {
        this.api = new Media();
    }

    init(done:PluginCallback): void {
        const jibo:Runtime = Runtime.instance;

        // Ignore services if running in unit tests
        if (jibo.runMode === jibo.RunMode.UNIT_TESTS) {
            return done();
        }

        this.api.init( () => {
	       done(null, this.api);
        });
    }
}

// register it as a jibo plugin
Runtime.registerPlugin(MediaPlugin, 'media', {
    depends: ['services'],
    api: true,
    name: 'media'
});

export default MediaPlugin;
