import {LPSEntity} from "jibo-common-types";
import {Clock, Time} from "animation-utilities";
import {SensoryType, PresenceType} from "./DataTypes";
import {PresenceEvents} from "./IDEvents";

let AnimationUtilities = require("animation-utilities");
let THREE = AnimationUtilities.THREE;
// let Time = AnimationUtilities.Time;

/**
 * @description
 * Record of any type of sensory input.
 * @memberOf jibo.lps.identity
 * @class SensoryRecord
 * @param {string} type Type of sensory recognition ('voice' or 'face').
 * @param {THREE.Vector3} position Position in space.
 * @param {object} rawData Raw LPS WS data.
 * @param {jibo.animate.Time} receivedAt Time this data was received.
 * @param {jibo.animate.Time} reportedTS The jibo TS at which it was reported.
 * @param {any} [id] ID of sensory record as provided from LPS Service.
 * @param {number} [confidence] Confidence in our recognition.
 */
export class SensoryRecord{

    /**
     * @type {string}
     */
    public type:SensoryType;

    /**
     * @type {THREE.Vector3}
     */
    public position:any = null;


    public raw:any;

    /**
     * @type {Time}
     */
    public receivedAt:Time;

    /**
     * @type {Time}
     */
    public reportedTS:Time;

    /**
     * @type {?}
     */
    public id:any;

    /**
     * @type {?number}
     */
    public confidence:number;

    /**
     * @type {?number}
     */
    public lastUpdate:Time;

    constructor(entity: LPSEntity, position:any, type:SensoryType, reportedTS: Time){
        // Get all of the info from LPS
        Object.assign(this, entity);
        this.type = type;

        // Additionally, have some convenience properties
        this.raw = entity;
        if(position !== null && position !== undefined){
            this.position = position;
        }

        this.id = entity.id;
        this.confidence = entity.confidence;
        this.receivedAt = Clock.currentTime();
        this.reportedTS =  reportedTS;
    }

    update(entity: LPSEntity) {
        Object.assign(this, entity);

        this.position = new THREE.Vector3(entity.position.x, entity.position.y, entity.position.z);
        this.lastUpdate = Clock.currentTime();
    }

}


/**
 * @description
 * Record of any type of presence
 * @memberOf jibo.lps.identity
 * @class PresenceRecord
 * @param {string} name Name (recognized ID) of present person.
 * @param {PresenceType} kind Kind of presence ('voice' 'motion' etc).
 * @param {boolean} present Whether or not presence is actively present around robot.
 * @param {number} [confidence] Confidence in this presence.
 */
export class PresenceRecord {

    /**
     * @type {string}
     * @description name of presence
     */
    public name:string;

    /**
     * @description kind of presence
     * @type {PresenceType}
     */
    public kind:PresenceType = null;

    /**
     * @description is still present
     * @type {Boolean}
     */
    public present:boolean;

    /**
     * @description confidence in presence
     * @type {Number}
     */
    public confidence:number;

    /**
     * @description Time presence was received
     * @type {Time}
     */
    public lastUpdate:Time;
    public events = new PresenceEvents();


    constructor(presence){
        // Get all of the info from LPS
        Object.assign(this, presence);
        this.lastUpdate = Clock.currentTime();
    }

    update(presence: PresenceRecord) {
        const presenceState = this.present;
        Object.assign(this, presence);
        // our presence state just changed!
        if(presenceState !== this.present) {
            //
            if(this.present === true) {
                this.events.presenceStarted.emit();
            }
            else {
                this.events.presenceEnded.emit();
            }
        }
        this.lastUpdate = Clock.currentTime();
    }
}

/**
 * @description
 * Record of a Speaker ID or recent speaker recognition.
 * @memberOf jibo.lps.identity
 * @class SpeakerRecord
 * @param {string} id ID of speaker recognized
 * @param {Array<number>} timestamp Time speaker was heard.
 */
export class SpeakerRecord {
    /**
     * @type {string}
     * @description name of speaker
     */
    public id:string;

    /**
     * @description timestamp of last spoke time
     * @type {PresenceType}
     */
    public timestamp:number[] = [0,0];

    constructor(speaker){
        // Get all of the info from LPS
        Object.assign(this, speaker);
    }

    update(speaker: SpeakerRecord) {
        Object.assign(this, speaker);
    }
}
