import {Event, EventContainer} from 'jibo-typed-events';

/**
 * Strongly-typed events emitted by MediaModel
 * @intdocs
 * @class jibo.kb.media.MediaModelEvents
 */
export default class MediaModelEvents extends EventContainer {

    /**
     * Event emitted whenever the media list has been updated (including on
     * mobile devices)
     * @name jibo.kb.media.MediaModelEvents#mediaListChanged
     * @type {Event}
     */
    public mediaListChanged: Event<void> =
        new Event<void>('Media list has changed');
};
