import Subcomponent from './Subcomponent';

/**
 * Manages qualities of a Component within a List.
 * @class ListMember
 * @memberof jibo.face
 * @intdocs
 */
class ListMember extends Subcomponent {

    /**
     * Subcomponent identifier.
     * @name jibo.face.ListMember.ID
     * @type {String}
     * @default 'ListMember'
     * @readOnly
     */
    public static get TYPE():string {return 'ListMember';}

    /**
     * Target position of list member.
     * @name jibo.face.ListMember.targetPosition
     * @type {PIXI.Point}
     */
    public targetPosition:PIXI.Point = null;

    /**
     * Velocity of list member.
     * @name jibo.face.ListMember.velocity
     * @type {PIXI.Point}
     */
    public velocity:PIXI.Point = null;

    /**
     * Offset from target.
     * @name jibo.face.ListMember.targetOffset
     * @type {Number}
     */
    public targetOffset:number = null;

    /**
     * If assets are loaded for owning Component.
     * @name jibo.face.ListMember.loaded
     * @type {Boolean}
     */
    public loaded:boolean = false;

    ///////////////////////////// CONSTRUCTION /////////////////////////////

    constructor() {
        super(ListMember.TYPE);
    }
    
}

export default ListMember;
