/**
 * Items for weighted rotation require an id and a weight.
 * @private
 */
export interface WeightedItem {
    id: string;
    weight: number;
}

/**
 * Because we need to modify weights, these will be created for each weighted item during
 * selection. Not exposed outside WeightedRotation.ts
 * @private
 */
class ItemStandin<T extends WeightedItem> implements WeightedItem {
    id: string;
    weight: number;
    valid: true;
    orig: T;
    
    constructor(original:T, usedDict:UsedDictionary) {
        this.orig = original;
        this.id = original.id;
        //if we have a partial use of an item, then subtract previous use from the weight
        if (usedDict && typeof usedDict[this.id] === 'number') {
            this.weight = original.weight - (usedDict[this.id] as number);
        } else {
            this.weight = original.weight;
        }
        this.valid = undefined;
    }
}

type UsedDictionary = {[id:string]:number|true};

/**
 * Selects an item from a list, using weighting and enforced rotation.
 * @param {WeightedItem[]} itemList The list of items to choose from.
 * @param {Function} validCheck Function to see if an individual item is valid.
 * @param {Object} [usedDict] Dictionary of used items, passed in by reference. If null, enforced
 *                            rotation is not used.
 * @private
 */
export function selectItem<T extends WeightedItem>(itemList:T[],
                                                    validCheck:(item:T)=>boolean,
                                                    usedDict?:UsedDictionary):T {
    if (!itemList || !itemList.length) {
        return null;
    }
    let itemOptions:ItemStandin<T>[] = [];
    let result:ItemStandin<T> = null;
    // prompts already used, tracked in case we need to do a reset
    let usedItems:ItemStandin<T>[] = [];

    //go through the prompts, getting valid ones, and setting aside used ones
    for (let item of itemList) {
        //if the item is completely out of the running, then put it aside for now
        if (usedDict && usedDict[item.id] === true) {
            usedItems.push(new ItemStandin(item, usedDict));
            continue;
        }
        //if it is valid, then hold onto it for selection, if it isn't then forget about it
        if (item.weight > 0 && validCheck(item)) {
            const standin = new ItemStandin(item, usedDict);
            //because the condition check of MIM prompts is potentially expensive, track that we
            //already did it in case we use this item again
            standin.valid = true;
            itemOptions.push(standin);
        }
    }
    //get a prompt if we can
    result = selectWeightedItem(itemOptions, usedItems, usedDict);
    //if we don't have a result, then we need to reset our used prompts and pick from those
    if (!result && usedItems.length) {
        //clear out the used dictionary data
        for (const prop in usedDict) {
            delete usedDict[prop];
        }
        //reset any modified weights and add them back into the item options
        for (let item of usedItems) {
            if (item.valid || validCheck(item.orig)) {
                item.weight = item.orig.weight;
                //add it back into the options list - it was emptied by the previous
                //selectWeightedItem() call, so is safe to add stuff to
                itemOptions.push(item);
            }
        }
        //last chance to get a prompt
        result = selectWeightedItem(itemOptions, usedItems, usedDict);
    }
    if (result && usedDict) {
        //track that we are going to use this prompt - this is a reference to the KB data, so
        //it will get saved when we save the KB Node
        const id = result.id;
        if (result.weight > 1) {
            //prompt has a reduced weight next time until it is fully used up
            usedDict[id] = usedDict[id] ? (usedDict[id] as number) + 1 : 1;
        } else {
            //prompt is fully out of the running
            usedDict[id] = true;
        }
    }
    return result ? result.orig : null;
}

/**
 * Selects an item from a list, using weighting and enforced rotation (if usedDict is passed in).
 * Is not exposed otuside of WeightedRotation.ts
 * @param {WeightedItem[]} items The list of items to choose from.
 * @param {WeightedItem[]} usedItems List of already used items, to add to if needed
 * @param {Object} [usedDict] Dictionary of used items, passed in by reference. If null, enforced
 *                            rotation is not used.
 * @private
 */
function selectWeightedItem<T extends WeightedItem>(items:T[], usedItems:T[], usedDict:UsedDictionary):T {
    if (items.length === 0) {
        return null;
    }
    let result:T = null;
    let totalWeight:number = 0;
    let length = items.length;
    //determine total weight
    for (let i = 0; i < length; ++i) {
        totalWeight += items[i].weight;
    }
    while (!result && length > 0) {
        //get a random number from 0 - n (not inclusive on the upper bound)
        const rand = Math.random() * totalWeight;
        let ongoingWeight = 0;
        //see which one we picked
        for (let i = 0; i < length; ++i) {
            ongoingWeight += items[i].weight;
            if (rand <= ongoingWeight) {
                result = items[i];
                break;
            }
        }
        //if the weight is less than 1, we have a chance to discard it as a result and pick a new
        //one in the next run of the while loop - only if enforcing rotation
        if (usedDict && result.weight < 1 && Math.random() >= result.weight) {
            usedItems.push(result);
            items.splice(items.indexOf(result), 1);
            usedDict[result.id] = true;
            totalWeight -= result.weight;
            length -= 1;
            result = null;
        }
    }
    return result;
}